(14418, 31, 'mobile', 'first-contentful-paint-3g', 'First Contentful Paint (3G)', 'n/a', '0.59', 'a:3:{s:11:\"description\";s:230:\"First Contentful Paint 3G marks the time at which the first text or image is painted while on a 3G network. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/first-contentful-paint\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:8:\"5460 ms\";}'),
