(12449, 1, 'desktop', 'uses-responsive-images', 'Настройте подходящий размер изображений', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:328:\"Чтобы сэкономить мобильные данные и ускорить загрузку, настройте подходящий размер изображений на странице. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/oversized-images\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:65:\"Потенциальная экономия данных: 6 КБ\";s:7:\"details\";O:8:\"stdClass\":5:{s:8:\"headings\";a:4:{i:0;O:8:\"stdClass\":2:{s:9:\"valueType\";s:9:\"thumbnail\";s:3:\"key\";s:3:\"url\";}i:1;O:8:\"stdClass\":3:{s:9:\"valueType\";s:3:\"url\";s:5:\"label\";s:3:\"URL\";s:3:\"key\";s:3:\"url\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:10:\"totalBytes\";s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:19:\"Размер (КБ)\";}i:3;O:8:\"stdClass\":3:{s:5:\"label\";s:63:\"Потенциальная экономия данных (КБ)\";s:3:\"key\";s:11:\"wastedBytes\";s:9:\"valueType\";s:5:\"bytes\";}}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:1:{i:0;O:8:\"stdClass\":4:{s:13:\"wastedPercent\";d:75;s:3:\"url\";s:175:\"<a href=\"https://armopt.ru/wp-content/uploads/2019/03/ranger-stilblue-150x150.jpg\" target=\"_blank\">https://armopt.ru/wp-content/uploads/2019/03/ranger-stilblue-150x150.jpg</a>\";s:10:\"totalBytes\";s:5:\"8,062\";s:11:\"wastedBytes\";s:5:\"6,047\";}}s:19:\"overallSavingsBytes\";d:6047;s:16:\"overallSavingsMs\";d:0;}}'),
(12443, 1, 'desktop', 'font-display', 'Настройте показ всего текста во время загрузки веб-шрифтов', 'table', '0.00', 'a:4:{s:11:\"description\";s:322:\"Чтобы пользователь мог видеть текст, пока веб-шрифты не загрузились, используйте функцию отображения шрифтов CSS. <a href=\"https://developers.google.com/web/updates/2016/02/font-display\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:6:\"binary\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:2:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:3:\"url\";s:8:\"itemType\";s:3:\"url\";s:4:\"text\";s:3:\"URL\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:8:\"wastedMs\";s:8:\"itemType\";s:2:\"ms\";s:4:\"text\";s:63:\"Потенциальная экономия данных (КБ)\";}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:11:{i:0;O:8:\"stdClass\":2:{s:8:\"wastedMs\";s:3:\"233\";s:3:\"url\";s:173:\"<a href=\"https://fonts.gstatic.com/s/opensans/v16/mem8YaGs126MiZpBA-UFVZ0b.woff2\" target=\"_blank\">https://fonts.gstatic.com/s/opensans/v16/mem8YaGs126MiZpBA-UFVZ0b.woff2</a>\";}i:1;O:8:\"stdClass\":2:{s:8:\"wastedMs\";s:3:\"230\";s:3:\"url\";s:179:\"<a href=\"https://armopt.ru/wp-content/themes/electro/assets/fonts/font-electro.woff\" target=\"_blank\">https://armopt.ru/wp-content/themes/electro/assets/fonts/font-electro.woff</a>\";}i:2;O:8:\"stdClass\":2:{s:3:\"url\";s:187:\"<a href=\"https://fonts.gstatic.com/s/opensans/v16/mem5YaGs126MiZpBA-UN7rgOVuhpOqc.woff2\" target=\"_blank\">https://fonts.gstatic.com/s/opensans/v16/mem5YaGs126MiZpBA-UN7rgOVuhpOqc.woff2</a>\";s:8:\"wastedMs\";s:3:\"228\";}i:3;O:8:\"stdClass\":2:{s:3:\"url\";s:187:\"<a href=\"https://armopt.ru/wp-content/themes/electro/assets/fonts/fa/fa-solid-900.woff2\" target=\"_blank\">https://armopt.ru/wp-content/themes/electro/assets/fonts/fa/fa-solid-900.woff2</a>\";s:8:\"wastedMs\";s:3:\"228\";}i:4;O:8:\"stdClass\":2:{s:8:\"wastedMs\";s:3:\"225\";s:3:\"url\";s:181:\"<a href=\"https://fonts.gstatic.com/s/opensans/v16/mem5YaGs126MiZpBA-UN7rgOUu