(12821, 7, 'mobile', 'uses-rel-preload', 'Настройте предварительную загрузку ключевых запросов', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:329:\"Чтобы загружать требуемые ресурсы в порядке приоритета, вам следует использовать <link rel=предварительную загрузку>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/preload\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:16:\"overallSavingsMs\";d:0;}}'),
(12822, 7, 'mobile', 'performance-budget', 'Performance budget', 'n/a', NULL, 'a:3:{s:11:\"description\";s:212:\"Keep the quantity and size of network requests under the targets set by the provided performance budget. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";}'),
