(12902, 8, 'mobile', 'mainthread-work-breakdown', 'Минимизируйте работу в основном потоке', 'table', '0.26', 'a:4:{s:11:\"description\";s:239:\"Рекомендуем сократить время на анализ, компиляцию и выполнение скриптов JS. Для этого вы можете уменьшить размер фрагментов кода JS.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:12:\"5,7 сек.\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:2:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:10:\"groupLabel\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:18:\"Категория\";}i:1;O:8:\"stdClass\":4:{s:4:\"text\";s:33:\"Потраченное время\";s:11:\"granularity\";d:1;s:3:\"key\";s:8:\"duration\";s:8:\"itemType\";s:2:\"ms\";}}s:5:\"items\";a:7:{i:0;O:8:\"stdClass\":3:{s:5:\"group\";s:16:\"scriptEvaluation\";s:8:\"duration\";s:5:\"3,781\";s:10:\"groupLabel\";s:17:\"Script Evaluation\";}i:1;O:8:\"stdClass\":3:{s:10:\"groupLabel\";s:14:\"Style & Layout\";s:5:\"group\";s:11:\"styleLayout\";s:8:\"duration\";s:3:\"654\";}i:2;O:8:\"stdClass\":3:{s:5:\"group\";s:5:\"other\";s:8:\"duration\";s:3:\"525\";s:10:\"groupLabel\";s:5:\"Other\";}i:3;O:8:\"stdClass\":3:{s:5:\"group\";s:9:\"parseHTML\";s:8:\"duration\";s:3:\"358\";s:10:\"groupLabel\";s:16:\"Parse HTML & CSS\";}i:4;O:8:\"stdClass\":3:{s:5:\"group\";s:20:\"paintCompositeRender\";s:8:\"duration\";s:3:\"167\";s:10:\"groupLabel\";s:9:\"Rendering\";}i:5;O:8:\"stdClass\":3:{s:5:\"group\";s:18:\"scriptParseCompile\";s:8:\"duration\";s:3:\"147\";s:10:\"groupLabel\";s:28:\"Script Parsing & Compilation\";}i:6;O:8:\"stdClass\":3:{s:5:\"group\";s:17:\"garbageCollection\";s:8:\"duration\";s:2:\"47\";s:10:\"groupLabel\";s:18:\"Garbage Collection\";}}s:4:\"type\";s:5:\"table\";}}'),
