(13159, 12, 'desktop', 'unminified-css', 'Уменьшите размер кода CSS', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:221:\"Уменьшение CSS-файлов может сократить нагрузку на сеть. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/minify-css\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":5:{s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:19:\"overallSavingsBytes\";d:0;}}'),
(13184, 12, 'mobile', 'performance-budget', 'Performance budget', 'n/a', NULL, 'a:3:{s:11:\"description\";s:212:\"Keep the quantity and size of network requests under the targets set by the provided performance budget. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";}'),
(13185, 12, 'mobile', 'unminified-javascript', 'Уменьшите размер кода JavaScript', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:283:\"Уменьшение файлов JavaScript может сократить размер фрагментов кода и время анализа скриптов. <a href=\"https://developers.google.com/speed/docs/insights/MinifyResources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":5:{s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:19:\"overallSavingsBytes\";d:0;s:16:\"overallSavingsMs\";d:0;}}'),
(13186, 12, 'mobile', 'redirects', 'Избегайте большого количества переадресаций', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:274:\"Переадресация может стать причиной дополнительной задержки при загрузке страницы. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/redirects\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:5:\"items\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}}}'),
(13187, 12, 'mobile', 'user-timings', 'Метки и промежутки пользовательского времени', 'table', NULL, 'a:4:{s:11:\"description\";s:390:\"Используйте User Timing API, чтобы измерить реальную производительность своего приложения во время ключевых моментов взаимодействия с пользователями. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/user-timing\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:0:{}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:0:{}}}'),
(13188, 12, 'mobile', 'resource-summary', 'Keep request counts low and transfer sizes small', 'table', NULL, 'a:4:{s:11:\"description\";s:191:\"To set budgets for the quantity and size of page resources, add a budget.json file. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:22:\"33 requests • 680 KB\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:5:\"label\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:13:\"Resource Type\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:12:\"requestCount\";s:8:\"itemType\";s:7:\"numeric\";s:4:\"text\";s:8:\"Requests\";}i:2;O:8:\"stdClass\":3:{s:4:\"text\";s:13:\"Transfer Size\";s:3:\"key\";s:4:\"size\";s:8:\"itemType\";s:5:\"bytes\";}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:9:{i:0;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"total\";s:5:\"label\";s:5:\"Total\";s:4:\"size\";d:696180;s:12:\"requestCount\";d:33;}i:1;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:6;s:12:\"resourceType\";s:6:\"script\";s:5:\"label\";s:6:\"Script\";s:4:\"size\";d:308892;}i:2;O:8:\"stdClass\":4:{s:5:\"label\";s:8:\"Document\";s:4:\"size\";d:202754;s:12:\"requestCount\";d:1;s:12:\"resourceType\";s:8:\"document\";}i:3;O:8:\"stdClass\":4:{s:5:\"label\";s:4:\"Font\";s:4:\"size\";d:161736;s:12:\"requestCount\";d:9;s:12:\"resourceType\";s:4:\"font\";}i:4;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:9;s:12:\"resourceType\";s:5:\"image\";s:5:\"label\";s:5:\"Image\";s:4:\"size\";d:14497;}i:5;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"other\";s:5:\"label\";s:5:\"Other\";s:4:\"size\";d:6680;s:12:\"requestCount\";d:7;}i:6;O:8:\"stdClass\":4:{s:5:\"label\";s:10:\"Stylesheet\";s:4:\"size\";d:1621;s:12:\"requestCount\";d:1;s:12:\"resourceType\";s:10:\"stylesheet\";}i:7;O:8:\"stdClass\":4:{s:5:\"label\";s:5:\"Media\";s:4:\"size\";d:0;s:12:\"requestCount\";d:0;s:12:\"resourceType\";s:5:\