(13282, 14, 'desktop', 'render-blocking-resources', 'Устраните ресурсы, блокирующие отображение', 'opportunity', '0.91', 'a:4:{s:11:\"description\";s:451:\"Некоторые ресурсы препятствуют загрузке контента страницы. Рекомендуем настроить загрузку необходимых ресурсов JS/CSS в первую очередь и отложить загрузку остальных ресурсов. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/blocking-resources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:69:\"Потенциальная экономия времени: 110 мс\";s:7:\"details\";O:8:\"stdClass\":4:{s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:1:{i:0;O:8:\"stdClass\":3:{s:10:\"totalBytes\";s:6:\"34,111\";s:8:\"wastedMs\";s:3:\"270\";s:3:\"url\";s:129:\"<a href=\"https://armopt.ru/wp-includes/js/jquery/jquery.js\" target=\"_blank\">https://armopt.ru/wp-includes/js/jquery/jquery.js</a>\";}}s:16:\"overallSavingsMs\";d:110;s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:3:\"url\";s:9:\"valueType\";s:3:\"url\";s:5:\"label\";s:3:\"URL\";}i:1;O:8:\"stdClass\":3:{s:5:\"label\";s:19:\"Размер (КБ)\";s:3:\"key\";s:10:\"totalBytes\";s:9:\"valueType\";s:5:\"bytes\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:8:\"wastedMs\";s:9:\"valueType\";s:10:\"timespanMs\";s:5:\"label\";s:63:\"Потенциальная экономия данных (КБ)\";}}}}'),
(13283, 14, 'desktop', 'uses-text-compression', 'Включите сжатие текста', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:333:\"Чтобы уменьшить расход трафика в сети, рекомендуем использовать сжатие для текстовых ресурсов (gzip, deflate или brotli). <a href=\"https://developers.google.com/web/tools/lighthouse/audits/text-compression\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":5:{s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}s:5:\"items\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:19:\"overallSavingsBytes\";d:0;}}'),
