(13279, 14, 'desktop', 'resource-summary', 'Keep request counts low and transfer sizes small', 'table', NULL, 'a:4:{s:11:\"description\";s:191:\"To set budgets for the quantity and size of page resources, add a budget.json file. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:22:\"40 requests • 826 KB\";s:7:\"details\";O:8:\"stdClass\":3:{s:4:\"type\";s:5:\"table\";s:5:\"items\";a:9:{i:0;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:40;s:12:\"resourceType\";s:5:\"total\";s:5:\"label\";s:5:\"Total\";s:4:\"size\";d:845777;}i:1;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:6;s:12:\"resourceType\";s:6:\"script\";s:5:\"label\";s:6:\"Script\";s:4:\"size\";d:308897;}i:2;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:1;s:12:\"resourceType\";s:8:\"document\";s:5:\"label\";s:8:\"Document\";s:4:\"size\";d:202393;}i:3;O:8:\"stdClass\":4:{s:5:\"label\";s:4:\"Font\";s:4:\"size\";d:192562;s:12:\"requestCount\";d:10;s:12:\"resourceType\";s:4:\"font\";}i:4;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:15;s:12:\"resourceType\";s:5:\"image\";s:5:\"label\";s:5:\"Image\";s:4:\"size\";d:133547;}i:5;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"other\";s:5:\"label\";s:5:\"Other\";s:4:\"size\";d:6779;s:12:\"requestCount\";d:7;}i:6;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:1;s:12:\"resourceType\";s:10:\"stylesheet\";s:5:\"label\";s:10:\"Stylesheet\";s:4:\"size\";d:1599;}i:7;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"media\";s:5:\"label\";s:5:\"Media\";s:4:\"size\";d:0;s:12:\"requestCount\";d:0;}i:8;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:11:\"third-party\";s:5:\"label\";s:11:\"Third-party\";s:4:\"size\";d:213054;s:12:\"requestCount\";d:23;}}s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:5:\"label\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:13:\"Resource Type\";}i:1;O:8:\"stdClass\":3:{s:8:\"itemType\";s:7:\"numeric\";s:3:\"key\";s:12