(13577, 19, 'desktop', 'unused-css-rules', 'Удалите неиспользуемый код CSS', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:401:\"Чтобы сократить расход трафика, удалите ненужные правила из таблиц стилей и отложите загрузку кода CSS, который не используется в верхней части страницы. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/unused-css\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:67:\"Потенциальная экономия данных: 162 КБ\";s:7:\"details\";O:8:\"stdClass\":5:{s:5:\"items\";a:1:{i:0;O:8:\"stdClass\":4:{s:3:\"url\";s:103:\".wp-block-audio figcaption{margin-top:.5em;margin-bottom:1em;color:#555d66;text-align:center; ... } ...\";s:10:\"totalBytes\";s:7:\"173,130\";s:11:\"wastedBytes\";s:7:\"165,967\";s:13:\"wastedPercent\";d:95.86275832642866;}}s:4:\"type\";s:11:\"opportunity\";s:19:\"overallSavingsBytes\";d:165967;s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:3:\"url\";s:9:\"valueType\";s:3:\"url\";s:5:\"label\";s:3:\"URL\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:10:\"totalBytes\";s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:19:\"Размер (КБ)\";}i:2;O:8:\"stdClass\":3:{s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:63:\"Потенциальная экономия данных (КБ)\";s:3:\"key\";s:11:\"wastedBytes\";}}}}'),
(13554, 19, 'desktop', 'dom-size', 'Сокращение размера структуры DOM', 'table', '0.93', 'a:4:{s:11:\"description\";s:960:\"Разработчики браузеров рекомендуют размещать на странице не более 1500 элементов DOM. Наилучшие показатели: глубина дерева – менее 32 элементов, количество дочерних и родительских элементов – менее 60. Сложная структура DOM может увеличить использование памяти, замедлить <a href=\"https://developers.google.com/web/fundamentals/performance/rendering/reduce-the-scope-and-complexity-of-style-calculations\" target=\"_blank\">вычисление стилей</a> и повысить затраты на <a href=\"https://developers.google.com/speed/articles/reflow\" target=\"_blank\">компоновку шаблонов</a>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/dom-size\" target=\"_blank\">Подробнее…</a>\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:20:\"765 элемента\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:4:\"text\";s:49:\"Статистический показатель\";s:3:\"key\";s:9:\"statistic\";s:8:\"itemType\";s:4:\"text\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:7:\"element\";s:8:\"itemType\";s:4:\"code\";s:4:\"text\";s:14:\"Элемент\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:5:\"value\";s:8:\"itemType\";s:7:\"numeric\";s:4:\"text\";s:16:\"Значение\";}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:3:{i:0;O:8:\"stdClass\":2:{s:5:\"value\";s:3:\"765\";s:9:\"statistic\";s:54:\"Общее количество элементов DOM\";}i:1;O:8:\"stdClass\":3:{s:5:\"value\";s:2:\"18\";s:9:\"statistic\";s:66:\"Максимальная глубина вложенности DOM\";s:7:\"element\";O:8:\"stdClass\":2:{s:4:\"type\";s:4:\"code\";s:5:\"value\";s:23:\"<span class=\"required\">\";}}i:2;O:8:\"stdClass\":3:{s:9:\"statistic\";s:71:\"Максимальное число дочерних элементов\";s:7:\"element\";O:8:\"stdClass\":2:{s:4:\"type\";s:4:\"code\";s:5:\"value\";s:74:\"<select name=\"product_cat\" id=\"product_cat\" class=\"postform resizeselect\">\";}s:5:\"value\";s:2:\"30\";}}}}'),
(13555, 19, 'desktop', 'uses-rel-preload', 'Настройте предварительную загрузку ключевых запросов', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:329:\"Чтобы загружать требуемые ресурсы в порядке приоритета, вам следует использовать <link rel=предварительную загрузку>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/preload\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}s:5:\"items\";a:0:{}s:4:\"type\";s:11:\"opportunity\";}}'),
(13556, 19, 'desktop', 'performance-budget', 'Performance budget', 'n/a', NULL, 'a:3:{s:11:\"description\";s:212:\"Keep the quantity and size of network requests under the targets set by the provided performance budget. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";}'),
(13557, 19, 'desktop', 'unminified-javascript', 'Уменьшите размер кода JavaScript', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:283:\"Уменьшение файлов JavaScript может сократить размер фрагментов кода и время анализа скриптов. <a href=\"https://developers.google.com/speed/docs/insights/MinifyResources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":5:{s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:19:\"overallSavingsBytes\";d:0;s:16:\"overallSavingsMs\";d:0;}}'),
(13558, 19, 'desktop', 'redirects', 'Избегайте большого количества переадресаций', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:274:\"Переадресация может стать причиной дополнительной задержки при загрузке страницы. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/redirects\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:16:\"overallSavingsMs\";d:0;}}'),
(13559, 19, 'desktop', 'user-timings', 'Метки и промежутки пользовательского времени', 'table', NULL, 'a:4:{s:11:\"description\";s:390:\"Используйте User Timing API, чтобы измерить реальную производительность своего приложения во время ключевых моментов взаимодействия с пользователями. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/user-timing\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:0:{}s:5:\"items\";a:0:{}s:4:\"type\";s:5:\"table\";}}'),
(13560, 19, 'desktop', 'resource-summary', 'Keep request counts low and transfer sizes small', 'table', NULL, 'a:4:{s:11:\"description\";s:191:\"To set budgets for the quantity and size of page resources, add a budget.json file. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:22:\"40 requests • 861 KB\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:5:\"label\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:13:\"Resource Type\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:12:\"requestCount\";s:8:\"itemType\";s:7:\"numeric\";s:4:\"text\";s:8:\"Requests\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:4:\"size\";s:8:\"itemType\";s:5:\"bytes\";s:4:\"text\";s:13:\"Transfer Size\";}}s:5:\"items\";a:9:{i:0;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:40;s:12:\"resourceType\";s:5:\"total\";s:5:\"label\";s:5:\"Total\";s:4:\"size\";d:882130;}i:1;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:6:\"script\";s:5:\"label\";s:6:\"Script\";s:4:\"size\";d:328409;s:12:\"requestCount\";d:5;}i:2;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:11;s:12:\"resourceType\";s:4:\"font\";s:5:\"label\";s:4:\"Font\";s:4:\"size\";d:206784;}i:3;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:1;s:12:\"resourceType\";s:8:\"document\";s:5:\"label\";s:8:\"Document\";s:4:\"size\";d:205066;}i:4;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"image\";s:5:\"label\";s:5:\"Image\";s:4:\"size\";d:133547;s:12:\"requestCount\";d:15;}i:5;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"other\";s:5:\"label\";s:5:\"Other\";s:4:\"size\";d:6725;s:12:\"requestCount\";d:7;}i:6;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:10:\"stylesheet\";s:5:\"label\";s:10:\"Stylesheet\";s:4:\"size\";d:1599;s:12:\"requestCount\";d:1;}i:7;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"media\";s:5:\"label\";s:5:\"Media\";s:4:\"size\";d:0;s:12:\"requestCount\";d:0;}i:8;O:8:\"std