(13861, 24, 'desktop', 'render-blocking-resources', 'Устраните ресурсы, блокирующие отображение', 'opportunity', '0.91', 'a:4:{s:11:\"description\";s:451:\"Некоторые ресурсы препятствуют загрузке контента страницы. Рекомендуем настроить загрузку необходимых ресурсов JS/CSS в первую очередь и отложить загрузку остальных ресурсов. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/blocking-resources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:69:\"Потенциальная экономия времени: 110 мс\";s:7:\"details\";O:8:\"stdClass\":4:{s:5:\"items\";a:1:{i:0;O:8:\"stdClass\":3:{s:3:\"url\";s:129:\"<a href=\"https://armopt.ru/wp-includes/js/jquery/jquery.js\" target=\"_blank\">https://armopt.ru/wp-includes/js/jquery/jquery.js</a>\";s:10:\"totalBytes\";s:6:\"34,111\";s:8:\"wastedMs\";s:3:\"310\";}}s:4:\"type\";s:11:\"opportunity\";s:16:\"overallSavingsMs\";d:110;s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:3:\"url\";s:9:\"valueType\";s:3:\"url\";s:5:\"label\";s:3:\"URL\";}i:1;O:8:\"stdClass\":3:{s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:19:\"Размер (КБ)\";s:3:\"key\";s:10:\"totalBytes\";}i:2;O:8:\"stdClass\":3:{s:9:\"valueType\";s:10:\"timespanMs\";s:5:\"label\";s:63:\"Потенциальная экономия данных (КБ)\";s:3:\"key\";s:8:\"wastedMs\";}}}}'),
(13862, 24, 'desktop', 'uses-optimized-images', 'Настройте эффективную кодировку изображений', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:288:\"Оптимизированные изображения загружаются быстрее и расходуют меньше мобильных данных. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/optimize-images\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:65:\"Потенциальная экономия данных: 8 КБ\";s:7:\"details\";O:8:\"stdClass\":5:{s:8:\"headings\";a:4:{i:0;O:8:\"stdClass\":2:{s:3:\"key\";s:3:\"url\";s:9:\"valueType\";s:9:\"thumbnail\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:3:\"url\";s:9:\"valueType\";s:3:\"url\";s:5:\"label\";s:3:\"URL\";}i:2;O:8:\"stdClass\":3:{s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:19:\"Размер (КБ)\";s:3:\"key\";s:10:\"totalBytes\";}i:3;O:8:\"stdClass\":3:{s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:63:\"Потенциальная экономия данных (КБ)\";s:3:\"key\";s:11:\"wastedBytes\";}}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:1:{i:0;O:8:\"stdClass\":5:{s:3:\"url\";s:179:\"<a href=\"https://armopt.ru/wp-content/uploads/2019/03/Bejsbolka-acu-pat-300x300.jpg\" target=\"_blank\">https://armopt.ru/wp-content/uploads/2019/03/Bejsbolka-acu-pat-300x300.jpg</a>\";s:12:\"fromProtocol\";b:1;s:10:\"totalBytes\";s:6:\"24,287\";s:13:\"isCrossOrigin\";b:0;s:11:\"wastedBytes\";s:5:\"8,417\";}}s:19:\"overallSavingsBytes\";d:8417;s:16:\"overallSavingsMs\";d:0;}}'),
