(14090, 27, 'desktop', 'user-timings', 'Метки и промежутки пользовательского времени', 'table', NULL, 'a:4:{s:11:\"description\";s:390:\"Используйте User Timing API, чтобы измерить реальную производительность своего приложения во время ключевых моментов взаимодействия с пользователями. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/user-timing\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":3:{s:5:\"items\";a:0:{}s:4:\"type\";s:5:\"table\";s:8:\"headings\";a:0:{}}}'),
