(14133, 27, 'mobile', 'first-contentful-paint-3g', 'First Contentful Paint (3G)', 'n/a', '0.21', 'a:3:{s:11:\"description\";s:230:\"First Contentful Paint 3G marks the time at which the first text or image is painted while on a 3G network. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/first-contentful-paint\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:8:\"8370 ms\";}'),
(14134, 27, 'mobile', 'uses-rel-preconnect', 'Используйте предварительное подключение к необходимым доменам', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:395:\"Чтобы быстро устанавливать соединение с необходимыми сторонними доменами, рекомендуем добавить ресурсные подсказки preconnect или dns-prefetch. <a href=\"https://developers.google.com/web/fundamentals/performance/resource-prioritization#preconnect\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}}}'),
(14135, 27, 'mobile', 'unminified-css', 'Уменьшите размер кода CSS', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:221:\"Уменьшение CSS-файлов может сократить нагрузку на сеть. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/minify-css\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":5:{s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:19:\"overallSavingsBytes\";d:0;}}'),
