(14147, 28, 'desktop', 'mainthread-work-breakdown', 'Минимизация работы в основном потоке', 'table', '0.96', 'a:4:{s:11:\"description\";s:239:\"Рекомендуем сократить время на анализ, компиляцию и выполнение скриптов JS. Для этого вы можете уменьшить размер фрагментов кода JS.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:12:\"1,6 сек.\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:2:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:10:\"groupLabel\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:18:\"Категория\";}i:1;O:8:\"stdClass\":4:{s:3:\"key\";s:8:\"duration\";s:8:\"itemType\";s:2:\"ms\";s:4:\"text\";s:33:\"Потраченное время\";s:11:\"granularity\";d:1;}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:7:{i:0;O:8:\"stdClass\":3:{s:5:\"group\";s:16:\"scriptEvaluation\";s:8:\"duration\";s:5:\"1,008\";s:10:\"groupLabel\";s:17:\"Script Evaluation\";}i:1;O:8:\"stdClass\":3:{s:5:\"group\";s:11:\"styleLayout\";s:8:\"duration\";s:3:\"224\";s:10:\"groupLabel\";s:14:\"Style & Layout\";}i:2;O:8:\"stdClass\":3:{s:5:\"group\";s:5:\"other\";s:8:\"duration\";s:3:\"129\";s:10:\"groupLabel\";s:5:\"Other\";}i:3;O:8:\"stdClass\":3:{s:5:\"group\";s:9:\"parseHTML\";s:8:\"duration\";s:2:\"77\";s:10:\"groupLabel\";s:16:\"Parse HTML & CSS\";}i:4;O:8:\"stdClass\":3:{s:10:\"groupLabel\";s:9:\"Rendering\";s:5:\"group\";s:20:\"paintCompositeRender\";s:8:\"duration\";s:2:\"62\";}i:5;O:8:\"stdClass\":3:{s:10:\"groupLabel\";s:18:\"Garbage Collection\";s:5:\"group\";s:17:\"garbageCollection\";s:8:\"duration\";s:2:\"47\";}i:6;O:8:\"stdClass\":3:{s:5:\"group\";s:18:\"scriptParseCompile\";s:8:\"duration\";s:2:\"35\";s:10:\"groupLabel\";s:28:\"Script Parsing & Compilation\";}}}}'),
