INSERT INTO `wp_gpi_page_reports` (`ID`, `page_id`, `strategy`, `rule_key`, `rule_name`, `rule_type`, `rule_score`, `rule_blocks`) VALUES
(14340, 30, 'desktop', 'network-server-latency', 'Задержка со стороны сервера', 'table', NULL, 'a:4:{s:11:\"description\";s:428:\"Задержки со стороны сервера могут влиять на скорость загрузки страниц. Высокое время отклика означает, что сервер перегружен или имеет низкую производительность. <a href=\"https://hpbn.co/primer-on-web-performance/#analyzing-the-resource-waterfall\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:7:\"0 мс\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:0:{}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:0:{}}}'),
