(14372, 30, 'mobile', 'dom-size', 'Сокращение размера структуры DOM', 'table', '0.95', 'a:4:{s:11:\"description\";s:960:\"Разработчики браузеров рекомендуют размещать на странице не более 1500 элементов DOM. Наилучшие показатели: глубина дерева – менее 32 элементов, количество дочерних и родительских элементов – менее 60. Сложная структура DOM может увеличить использование памяти, замедлить <a href=\"https://developers.google.com/web/fundamentals/performance/rendering/reduce-the-scope-and-complexity-of-style-calculations\" target=\"_blank\">вычисление стилей</a> и повысить затраты на <a href=\"https://developers.google.com/speed/articles/reflow\" target=\"_blank\">компоновку шаблонов</a>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/dom-size\" target=\"_blank\">Подробнее…</a>\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:20:\"709 элемента\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:4:\"text\";s:49:\"Статистический показатель\";s:3:\"key\";s:9:\"statistic\";s:8:\"itemType\";s:4:\"text\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:7:\"element\";s:8:\"itemType\";s:4:\"code\";s:4:\"text\";s:14:\"Элемент\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:5:\"value\";s:8:\"itemType\";s:7:\"numeric\";s:4:\"text\";s:16:\"Значение\";}}s:5:\"items\";a:3:{i:0;O:8:\"stdClass\":2:{s:5:\"value\";s:3:\"709\";s:9:\"statistic\";s:54:\"Общее количество элементов DOM\";}i:1;O:8:\"stdClass\":3:{s:5:\"value\";s:2:\"17\";s:9:\"statistic\";s:66:\"Максимальная глубина вложенности DOM\";s:7:\"element\";O:8:\"stdClass\":2:{s:4:\"type\";s:4:\"code\";s:5:\"value\";s:6:\"<span>\";}}i:2;O:8:\"stdClass\":3:{s:5:\"value\";s:2:\"30\";s:9:\"statistic\";s:71:\"Максимальное число дочерних элементов\";s:7:\"element\";O:8:\"stdClass\":2:{s:4:\"type\";s:4:\"code\";s:5:\"value\";s:74:\"<select name=\"product_cat\" id=\"product_cat\" class=\"postform resizeselect\">\";}}}s:4:\"type\";s:5:\"table\";}}'),
(14373, 30, 'mobile', 'uses-rel-preload', 'Настройте предварительную загрузку ключевых запросов', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:329:\"Чтобы загружать требуемые ресурсы в порядке приоритета, вам следует использовать <link rel=предварительную загрузку>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/preload\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:16:\"overallSavingsMs\";d:0;}}'),
(14374, 30, 'mobile', 'performance-budget', 'Performance budget', 'n/a', NULL, 'a:3:{s:11:\"description\";s:212:\"Keep the quantity and size of network requests under the targets set by the provided performance budget. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";}'),
