(14388, 31, 'desktop', 'render-blocking-resources', 'Устраните ресурсы, блокирующие отображение', 'opportunity', '0.98', 'a:4:{s:11:\"description\";s:451:\"Некоторые ресурсы препятствуют загрузке контента страницы. Рекомендуем настроить загрузку необходимых ресурсов JS/CSS в первую очередь и отложить загрузку остальных ресурсов. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/blocking-resources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:68:\"Потенциальная экономия времени: 30 мс\";s:7:\"details\";O:8:\"stdClass\":4:{s:16:\"overallSavingsMs\";d:30;s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:3:\"url\";s:9:\"valueType\";s:3:\"url\";s:5:\"label\";s:3:\"URL\";}i:1;O:8:\"stdClass\":3:{s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:19:\"Размер (КБ)\";s:3:\"key\";s:10:\"totalBytes\";}i:2;O:8:\"stdClass\":3:{s:5:\"label\";s:63:\"Потенциальная экономия данных (КБ)\";s:3:\"key\";s:8:\"wastedMs\";s:9:\"valueType\";s:10:\"timespanMs\";}}s:5:\"items\";a:1:{i:0;O:8:\"stdClass\":3:{s:3:\"url\";s:129:\"<a href=\"https://armopt.ru/wp-includes/js/jquery/jquery.js\" target=\"_blank\">https://armopt.ru/wp-includes/js/jquery/jquery.js</a>\";s:10:\"totalBytes\";s:6:\"34,111\";s:8:\"wastedMs\";s:3:\"190\";}}s:4:\"type\";s:11:\"opportunity\";}}'),
