(14438, 32, 'desktop', 'dom-size', 'Сокращение размера структуры DOM', 'table', '0.94', 'a:4:{s:11:\"description\";s:960:\"Разработчики браузеров рекомендуют размещать на странице не более 1500 элементов DOM. Наилучшие показатели: глубина дерева – менее 32 элементов, количество дочерних и родительских элементов – менее 60. Сложная структура DOM может увеличить использование памяти, замедлить <a href=\"https://developers.google.com/web/fundamentals/performance/rendering/reduce-the-scope-and-complexity-of-style-calculations\" target=\"_blank\">вычисление стилей</a> и повысить затраты на <a href=\"https://developers.google.com/speed/articles/reflow\" target=\"_blank\">компоновку шаблонов</a>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/dom-size\" target=\"_blank\">Подробнее…</a>\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:20:\"723 элемента\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:9:\"statistic\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:49:\"Статистический показатель\";}i:1;O:8:\"stdClass\":3:{s:8:\"itemType\";s:4:\"code\";s:3:\"key\";s:7:\"element\";s:4:\"text\";s:14:\"Элемент\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:5:\"value\";s:8:\"itemType\";s:7:\"numeric\";s:4:\"text\";s:16:\"Значение\";}}s:5:\"items\";a:3:{i:0;O:8:\"stdClass\":2:{s:5:\"value\";s:3:\"723\";s:9:\"statistic\";s:54:\"Общее количество элементов DOM\";}i:1;O:8:\"stdClass\":3:{s:5:\"value\";s:2:\"17\";s:9:\"statistic\";s:66:\"Максимальная глубина вложенности DOM\";s:7:\"element\";O:8:\"stdClass\":2:{s:4:\"type\";s:4:\"code\";s:5:\"value\";s:6:\"<span>\";}}i:2;O:8:\"stdClass\":3:{s:5:\"value\";s:2:\"30\";s:9:\"statistic\";s:71:\"Максимальное число дочерних элементов\";s:7:\"element\";O:8:\"stdClass\":2:{s:5:\"value\";s:74:\"<select name=\"product_cat\" id=\"product_cat\" class=\"postform resizeselect\">\";s:4:\"type\";s:4:\"code\";}}}s:4:\"type\";s:5:\"table\";}}'),
(14466, 32, 'mobile', 'resource-summary', 'Keep request counts low and transfer sizes small', 'table', NULL, 'a:4:{s:11:\"description\";s:191:\"To set budgets for the quantity and size of page resources, add a budget.json file. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:22:\"35 requests • 694 KB\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:8:\"itemType\";s:4:\"text\";s:3:\"key\";s:5:\"label\";s:4:\"text\";s:13:\"Resource Type\";}i:1;O:8:\"stdClass\":3:{s:4:\"text\";s:8:\"Requests\";s:3:\"key\";s:12:\"requestCount\";s:8:\"itemType\";s:7:\"numeric\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:4:\"size\";s:8:\"itemType\";s:5:\"bytes\";s:4:\"text\";s:13:\"Transfer Size\";}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:9:{i:0;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:35;s:12:\"resourceType\";s:5:\"total\";s:5:\"label\";s:5:\"Total\";s:4:\"size\";d:710994;}i:1;O:8:\"stdClass\":4:{s:5:\"label\";s:6:\"Script\";s:4:\"size\";d:308897;s:12:\"requestCount\";d:6;s:12:\"resourceType\";s:6:\"script\";}i:2;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:8:\"document\";s:5:\"label\";s:8:\"Document\";s:4:\"size\";d:202127;s:12:\"requestCount\";d:1;}i:3;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:4:\"font\";s:5:\"label\";s:4:\"Font\";s:4:\"size\";d:177184;s:12:\"requestCount\";d:11;}i:4;O:8:\"stdClass\":4:{s:5:\"label\";s:5:\"Image\";s:4:\"size\";d:14497;s:12:\"requestCount\";d:9;s:12:\"resourceType\";s:5:\"image\";}i:5;O:8:\"stdClass\":4:{s:5:\"label\";s:5:\"Other\";s:4:\"size\";d:6668;s:12:\"requestCount\";d:7;s:12:\"resourceType\";s:5:\"other\";}i:6;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:10:\"stylesheet\";s:5:\"label\";s:10:\"Stylesheet\";s:4:\"size\";d:1621;s:12:\"requestCount\";d:1;}i:7;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:0;s:12:\"resourceType\";s:5:\"media\";s:5:\"label\";s:5:\"Media\";s:4:\"s