(14580, 34, 'desktop', 'performance-budget', 'Performance budget', 'n/a', NULL, 'a:3:{s:11:\"description\";s:212:\"Keep the quantity and size of network requests under the targets set by the provided performance budget. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";}'),
(14581, 34, 'desktop', 'unminified-javascript', 'Уменьшите размер кода JavaScript', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:283:\"Уменьшение файлов JavaScript может сократить размер фрагментов кода и время анализа скриптов. <a href=\"https://developers.google.com/speed/docs/insights/MinifyResources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":5:{s:5:\"items\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:19:\"overallSavingsBytes\";d:0;s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}}}'),
(14582, 34, 'desktop', 'redirects', 'Избегайте большого количества переадресаций', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:274:\"Переадресация может стать причиной дополнительной задержки при загрузке страницы. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/redirects\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:16:\"overallSavingsMs\";d:0;}}'),
(14602, 34, 'mobile', 'resource-summary', 'Keep request counts low and transfer sizes small', 'table', NULL, 'a:4:{s:11:\"description\";s:191:\"To set budgets for the quantity and size of page resources, add a budget.json file. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:22:\"32 requests • 643 KB\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:4:\"text\";s:13:\"Resource Type\";s:8:\"itemType\";s:4:\"text\";s:3:\"key\";s:5:\"label\";}i:1;O:8:\"stdClass\":3:{s:8:\"itemType\";s:7:\"numeric\";s:3:\"key\";s:12:\"requestCount\";s:4:\"text\";s:8:\"Requests\";}i:2;O:8:\"stdClass\":3:{s:4:\"text\";s:13:\"Transfer Size\";s:3:\"key\";s:4:\"size\";s:8:\"itemType\";s:5:\"bytes\";}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:9:{i:0;O:8:\"stdClass\":4:{s:5:\"label\";s:5:\"Total\";s:4:\"size\";d:657935;s:12:\"requestCount\";d:32;s:12:\"resourceType\";s:5:\"total\";}i:1;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:6;s:12:\"resourceType\";s:6:\"script\";s:5:\"label\";s:6:\"Script\";s:4:\"size\";d:308897;}i:2;O:8:\"stdClass\":4:{s:5:\"label\";s:8:\"Document\";s:4:\"size\";d:168915;s:12:\"requestCount\";d:1;s:12:\"resourceType\";s:8:\"document\";}i:3;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:4:\"font\";s:5:\"label\";s:4:\"Font\";s:4:\"size\";d:161735;s:12:\"requestCount\";d:9;}i:4;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:8;s:12:\"resourceType\";s:5:\"image\";s:5:\"label\";s:5:\"Image\";s:4:\"size\";d:9966;}i:5;O:8:\"stdClass\":4:{s:5:\"label\";s:5:\"Other\";s:4:\"size\";d:6801;s:12:\"requestCount\";d:7;s:12:\"resourceType\";s:5:\"other\";}i:6;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:10:\"stylesheet\";s:5:\"label\";s:10:\"Stylesheet\";s:4:\"size\";d:1621;s:12:\"requestCount\";d:1;}i:7;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"media\";s:5:\"label\";s:5:\"Media\";s:4:\"size\";d:0;s:12:\"requestCoun