(14783, 36, 'mobile', 'max-potential-fid', 'Максимальная потенциальная задержка FID', 'n/a', '0.02', 'a:3:{s:11:\"description\";s:207:\"Потенциальная задержка после первого ввода (FID) показывает максимальное время выполнения задачи в миллисекундах\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:9:\"680 мс\";}'),
(14784, 36, 'mobile', 'network-rtt', 'Время прохождения сигнала сети', 'table', NULL, 'a:4:{s:11:\"description\";s:494:\"Время прохождения сигнала сети (RTT) напрямую влияет на производительность сайта. Высокое время прохождения сигнала означает, что серверы расположены слишком далеко от пользователя и сайт будет работать медленнее. <a href=\"https://hpbn.co/primer-on-latency-and-bandwidth/\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:7:\"0 мс\";s:7:\"details\";O:8:\"stdClass\":3:{s:4:\"type\";s:5:\"table\";s:5:\"items\";a:0:{}s:8:\"headings\";a:0:{}}}'),
(14796, 37, 'desktop', 'dom-size', 'Сокращение размера структуры DOM', 'table', '0.93', 'a:4:{s:11:\"description\";s:960:\"Разработчики браузеров рекомендуют размещать на странице не более 1500 элементов DOM. Наилучшие показатели: глубина дерева – менее 32 элементов, количество дочерних и родительских элементов – менее 60. Сложная структура DOM может увеличить использование памяти, замедлить <a href=\"https://developers.google.com/web/fundamentals/performance/rendering/reduce-the-scope-and-complexity-of-style-calculations\" target=\"_blank\">вычисление стилей</a> и повысить затраты на <a href=\"https://developers.google.com/speed/articles/reflow\" target=\"_blank\">компоновку шаблонов</a>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/dom-size\" target=\"_blank\">Подробнее…</a>\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:20:\"763 элемента\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:9:\"statistic\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:49:\"Статистический показатель\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:7:\"element\";s:8:\"itemType\";s:4:\"code\";s:4:\"text\";s:14:\"Элемент\";}i:2;O:8:\"stdClass\":3:{s:4:\"text\";s:16:\"Значение\";s:3:\"key\";s:5:\"value\";s:8:\"itemType\";s:7:\"numeric\";}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:3:{i:0;O:8:\"stdClass\":2:{s:9:\"statistic\";s:54:\"Общее количество элементов DOM\";s:5:\"value\";s:3:\"763\";}i:1;O:8:\"stdClass\":3:{s:5:\"value\";s:2:\"17\";s:9:\"statistic\";s:66:\"Максимальная глубина вложенности DOM\";s:7:\"element\";O:8:\"stdClass\":2:{s:5:\"value\";s:6:\"<span>\";s:4:\"type\";s:4:\"code\";}}i:2;O:8:\"stdClass\":3:{s:5:\"value\";s:2:\"30\";s:9:\"statistic\";s:71:\"Максимальное число дочерних элементов\";s:7:\"element\";O:8:\"stdClass\":2:{s:4:\"type\";s:4:\"code\";s:5:\"value\";s:74:\"<select name=\"product_cat\" id=\"product_cat\" class=\"postform resizeselect\">\";}}}}}'),
(14797, 37, 'desktop', 'uses-rel-preload', 'Настройте предварительную загрузку ключевых запросов', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:329:\"Чтобы загружать требуемые ресурсы в порядке приоритета, вам следует использовать <link rel=предварительную загрузку>. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/preload\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}}}'),
(14798, 37, 'desktop', 'performance-budget', 'Performance budget', 'n/a', NULL, 'a:3:{s:11:\"description\";s:212:\"Keep the quantity and size of network requests under the targets set by the provided performance budget. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";}'),
(14799, 37, 'desktop', 'unminified-javascript', 'Уменьшите размер кода JavaScript', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:283:\"Уменьшение файлов JavaScript может сократить размер фрагментов кода и время анализа скриптов. <a href=\"https://developers.google.com/speed/docs/insights/MinifyResources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":5:{s:16:\"overallSavingsMs\";d:0;s:8:\"headings\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:0:{}s:19:\"overallSavingsBytes\";d:0;}}'),
(14800, 37, 'desktop', 'redirects', 'Избегайте большого количества переадресаций', 'opportunity', '1.00', 'a:4:{s:11:\"description\";s:274:\"Переадресация может стать причиной дополнительной задержки при загрузке страницы. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/redirects\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":4:{s:8:\"headings\";a:0:{}s:5:\"items\";a:0:{}s:4:\"type\";s:11:\"opportunity\";s:16:\"overallSavingsMs\";d:0;}}'),
(14801, 37, 'desktop', 'user-timings', 'Метки и промежутки пользовательского времени', 'table', NULL, 'a:4:{s:11:\"description\";s:390:\"Используйте User Timing API, чтобы измерить реальную производительность своего приложения во время ключевых моментов взаимодействия с пользователями. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/user-timing\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";s:7:\"details\";O:8:\"stdClass\":3:{s:5:\"items\";a:0:{}s:4:\"type\";s:5:\"table\";s:8:\"headings\";a:0:{}}}'),
(14802, 37, 'desktop', 'resource-summary', 'Keep request counts low and transfer sizes small', 'table', NULL, 'a:4:{s:11:\"description\";s:191:\"To set budgets for the quantity and size of page resources, add a budget.json file. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:22:\"41 requests • 857 KB\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:4:\"text\";s:13:\"Resource Type\";s:3:\"key\";s:5:\"label\";s:8:\"itemType\";s:4:\"text\";}i:1;O:8:\"stdClass\":3:{s:8:\"itemType\";s:7:\"numeric\";s:3:\"key\";s:12:\"requestCount\";s:4:\"text\";s:8:\"Requests\";}i:2;O:8:\"stdClass\":3:{s:8:\"itemType\";s:5:\"bytes\";s:3:\"key\";s:4:\"size\";s:4:\"text\";s:13:\"Transfer Size\";}}s:4:\"type\";s:5:\"table\";s:5:\"items\";a:9:{i:0;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"total\";s:5:\"label\";s:5:\"Total\";s:4:\"size\";d:877660;s:12:\"requestCount\";d:41;}i:1;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:6;s:12:\"resourceType\";s:6:\"script\";s:5:\"label\";s:6:\"Script\";s:4:\"size\";d:308897;}i:2;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:4:\"font\";s:5:\"label\";s:4:\"Font\";s:4:\"size\";d:205142;s:12:\"requestCount\";d:11;}i:3;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:8:\"document\";s:5:\"label\";s:8:\"Document\";s:4:\"size\";d:203521;s:12:\"requestCount\";d:1;}i:4;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:15;s:12:\"resourceType\";s:5:\"image\";s:5:\"label\";s:5:\"Image\";s:4:\"size\";d:151741;}i:5;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"other\";s:5:\"label\";s:5:\"Other\";s:4:\"size\";d:6760;s:12:\"requestCount\";d:7;}i:6;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:10:\"stylesheet\";s:5:\"label\";s:10:\"Stylesheet\";s:4:\"size\";d:1599;s:12:\"requestCount\";d:1;}i:7;O:8:\"stdClass\":4:{s:5:\"label\";s:5:\"Media\";s:4:\"size\";d:0;s:12:\"requestCount\";d:0;s:12:\"resourceType\";s