(14316, 40, 'mobile', 'render-blocking-resources', 'Устраните ресурсы, блокирующие отображение', 'opportunity', '0.88', 'a:4:{s:11:\"description\";s:451:\"Некоторые ресурсы препятствуют загрузке контента страницы. Рекомендуем настроить загрузку необходимых ресурсов JS/CSS в первую очередь и отложить загрузку остальных ресурсов. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/blocking-resources\" target=\"_blank\">Подробнее…</a>.\";s:18:\"score_display_mode\";s:7:\"numeric\";s:13:\"display_value\";s:69:\"Потенциальная экономия времени: 150 мс\";s:7:\"details\";O:8:\"stdClass\":4:{s:4:\"type\";s:11:\"opportunity\";s:5:\"items\";a:1:{i:0;O:8:\"stdClass\":3:{s:8:\"wastedMs\";s:3:\"630\";s:3:\"url\";s:129:\"<a href=\"https://armopt.ru/wp-includes/js/jquery/jquery.js\" target=\"_blank\">https://armopt.ru/wp-includes/js/jquery/jquery.js</a>\";s:10:\"totalBytes\";s:6:\"34,111\";}}s:16:\"overallSavingsMs\";d:150;s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:3:\"url\";s:9:\"valueType\";s:3:\"url\";s:5:\"label\";s:3:\"URL\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:10:\"totalBytes\";s:9:\"valueType\";s:5:\"bytes\";s:5:\"label\";s:19:\"Размер (КБ)\";}i:2;O:8:\"stdClass\":3:{s:3:\"key\";s:8:\"wastedMs\";s:9:\"valueType\";s:10:\"timespanMs\";s:5:\"label\";s:63:\"Потенциальная экономия данных (КБ)\";}}}}'),
(14313, 40, 'mobile', 'resource-summary', 'Keep request counts low and transfer sizes small', 'table', NULL, 'a:4:{s:11:\"description\";s:191:\"To set budgets for the quantity and size of page resources, add a budget.json file. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:11:\"informative\";s:13:\"display_value\";s:22:\"33 requests • 679 KB\";s:7:\"details\";O:8:\"stdClass\":3:{s:8:\"headings\";a:3:{i:0;O:8:\"stdClass\":3:{s:3:\"key\";s:5:\"label\";s:8:\"itemType\";s:4:\"text\";s:4:\"text\";s:13:\"Resource Type\";}i:1;O:8:\"stdClass\":3:{s:3:\"key\";s:12:\"requestCount\";s:8:\"itemType\";s:7:\"numeric\";s:4:\"text\";s:8:\"Requests\";}i:2;O:8:\"stdClass\":3:{s:4:\"text\";s:13:\"Transfer Size\";s:3:\"key\";s:4:\"size\";s:8:\"itemType\";s:5:\"bytes\";}}s:5:\"items\";a:9:{i:0;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:33;s:12:\"resourceType\";s:5:\"total\";s:5:\"label\";s:5:\"Total\";s:4:\"size\";d:695433;}i:1;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:6;s:12:\"resourceType\";s:6:\"script\";s:5:\"label\";s:6:\"Script\";s:4:\"size\";d:308897;}i:2;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:1;s:12:\"resourceType\";s:8:\"document\";s:5:\"label\";s:8:\"Document\";s:4:\"size\";d:201991;}i:3;O:8:\"stdClass\":4:{s:12:\"requestCount\";d:9;s:12:\"resourceType\";s:4:\"font\";s:5:\"label\";s:4:\"Font\";s:4:\"size\";d:161735;}i:4;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"image\";s:5:\"label\";s:5:\"Image\";s:4:\"size\";d:14497;s:12:\"requestCount\";d:9;}i:5;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:5:\"other\";s:5:\"label\";s:5:\"Other\";s:4:\"size\";d:6692;s:12:\"requestCount\";d:7;}i:6;O:8:\"stdClass\":4:{s:12:\"resourceType\";s:10:\"stylesheet\";s:5:\"label\";s:10:\"Stylesheet\";s:4:\"size\";d:1621;s:12:\"requestCount\";d:1;}i:7;O:8:\"stdClass\":4:{s:5:\"label\";s:5:\"Media\";s:4:\"size\";d:0;s:12:\"requestCount\";d:0;s:12:\"resourceType\";s:5:\"media\";}i:8;O:8:\"stdClas