(14619, 41, 'desktop', 'performance-budget', 'Performance budget', 'n/a', NULL, 'a:3:{s:11:\"description\";s:212:\"Keep the quantity and size of network requests under the targets set by the provided performance budget. <a href=\"https://developers.google.com/web/tools/lighthouse/audits/budgets\" target=\"_blank\">Learn more</a>.\";s:18:\"score_display_mode\";s:13:\"notApplicable\";s:13:\"display_value\";s:0:\"\";}'),
