32x32.png\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"YITH\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"https://yithemes.com\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"width\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:6:\"height\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"32\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:122:\"WordPress lovers gathering again in Turin, this time under the viral slogan #keepcalmandclearcache – WordCamp Turin 2019\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:150:\"https://yithemes.com/blog/events/wordpress-lovers-gathering-again-in-turin-this-time-under-the-viral-slogan-keepcalmandclearcache-wordcamp-turin-2019/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:158:\"https://yithemes.com/blog/events/wordpress-lovers-gathering-again-in-turin-this-time-under-the-viral-slogan-keepcalmandclearcache-wordcamp-turin-2019/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 29 Apr 2019 14:13:02 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://yithemes.com/?p=1035893\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:344:\"It’s an annual tradition now for us at YITH, we couldn’t miss the awesome event organized by the WordPress community in Turin: WordCamp Turin 2019! Hosted in the location of Toolbox Coworking, it started on April 5th with the Contributor Day. In the big room named “Keynote”, the attendees were crowding around the tables with [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"YITH Support Team\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:6171:\"<p dir=\"ltr\">It’s an annual tradition now for us at YITH, we couldn’t miss the <strong>awesome event organized by the WordPress community in Turin</strong>: WordCamp Turin 2019!</p>\n<p dir=\"ltr\">Hosted in the location of Toolbox Coworking, it started on April 5th with the Contributor Day.</p>\n<p dir=\"ltr\">In the big room named “Keynote”, the attendees were crowding around the tables with one common goal, contributing to WordPress for one whole day, be they developers, graphic designers, polyglots, marketers or mere WordPress lovers.</p>\n<p dir=\"ltr\">As soon as we arrived, after taking a cup of coffee, we sat down at <strong>WP Core table and worked on contributing to WordPress</strong> as well.</p>\n<p dir=\"ltr\">The location was perfect for the Contributor Day (as it was in the past years too) and everything was organised with great attention to the detail.</p>\n<p dir=\"ltr\">Saturday 6th April was the high point of the event: the conference day!</p>\n<p dir=\"ltr\">The first speeches began at 9:30 with topics ranging from development, content management, SEO, marketing, business and much more.</p>\n<p dir=\"ltr\"><a href=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4.jpg\"><img class=\"alignnone size-full wp-image-1037085\" src=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4.jpg\" alt=\"\" width=\"2126\" height=\"785\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4.jpg 2126w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4-300x111.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4-768x284.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4-1024x378.jpg 1024w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4-261x96.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4-311x115.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4-363x134.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-4-270x100.jpg 270w\" sizes=\"(max-width: 2126px) 100vw, 2126px\" /></a></p>\n<p dir=\"ltr\">Right from the start of the event and during the breaks, our t-shirts literally flew off the shelves!</p>\n<p dir=\"ltr\">The slogan printed on them <strong>“Keep calm and clear cache”</strong> won all people approaching the booth, they couldn’t help asking for one! Some of them use to collect all our t-shirts and could not absolutely miss this new piece.</p>\n<p><a href=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2.jpg\"><img class=\"alignnone size-full wp-image-1037086\" src=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2.jpg\" alt=\"\" width=\"1672\" height=\"785\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2.jpg 1672w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2-300x141.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2-768x361.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2-1024x481.jpg 1024w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2-261x123.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2-311x146.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2-363x170.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-2-270x127.jpg 270w\" sizes=\"(max-width: 1672px) 100vw, 1672px\" /></a></p>\n<p dir=\"ltr\">Among the many people that stopped to talk, to our great satisfaction, we could notice that most of them are using our products. As developers, it made us proud to hear statements like “I’ve been using your plugins for a while now, and I couldn’t do without them”.</p>\n<p><a href=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1.jpg\"><img class=\"alignnone size-full wp-image-1037087\" src=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1.jpg\" alt=\"\" width=\"1672\" height=\"785\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1.jpg 1672w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1-300x141.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1-768x361.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1-1024x481.jpg 1024w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1-261x123.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1-311x146.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1-363x170.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-1-270x127.jpg 270w\" sizes=\"(max-width: 1672px) 100vw, 1672px\" /></a></p>\n<p><a href=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3.jpg\"><img class=\"alignnone size-full wp-image-1037088\" src=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3.jpg\" alt=\"\" width=\"2012\" height=\"735\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3.jpg 2012w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3-300x110.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3-768x281.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3-1024x374.jpg 1024w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3-261x95.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3-311x114.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3-363x133.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/Senza-titolo-3-270x99.jpg 270w\" sizes=\"(max-width: 2012px) 100vw, 2012px\" /></a></p>\n<p dir=\"ltr\">We also had the opportunity and pleasure to meet familiar faces and old friends. Not only could we hold business conversations with all of them, but also we spent a wonderful evening at the after party, held in the same location: board games, ping-pong, table football, karaoke… well, we did not miss anything!</p>\n<p dir=\"ltr\"><strong>We want to thank both all the organisers and volunteers</strong> that worked hard to make the WordCamp result in such a successful and enjoyable event, and all the attendees who took part in the event: it couldn’t have been so great without them!</p>\n<p dir=\"ltr\">\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:155:\"https://yithemes.com/blog/events/wordpress-lovers-gathering-again-in-turin-this-time-under-the-viral-slogan-keepcalmandclearcache-wordcamp-turin-2019/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"Keep Calm and Clear your Cache – WordCamp London 2019\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://yithemes.com/blog/events/keep-calm-and-clear-your-cache-wordcamp-london-2019/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:93:\"https://yithemes.com/blog/events/keep-calm-and-clear-your-cache-wordcamp-london-2019/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 16 Apr 2019 15:37:07 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://yithemes.com/?p=1034532\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:338:\"Keep Calm and Clear your Cache This was not just a WordCamp it was a WordCamp multiplied by three… London, Madrid and Turin all supporting #yithevents… But there was an added connection, which was the hashtag that linked us all &#8211; #keepcalmandclearcache. The t-shirts, with the motto printed on, that we gave to our new [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Ausilia\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:13334:\"<h2 dir=\"ltr\">Keep Calm and Clear your Cache</h2>\n<p dir=\"ltr\">This was not just a WordCamp it was a WordCamp multiplied by three… London, Madrid and Turin all supporting #yithevents… But there was an added connection, which was the hashtag that linked us all &#8211; #keepcalmandclearcache. The t-shirts, with the motto printed on, that we gave to our new and existing customers went down a storm.</p>\n<p dir=\"ltr\"><img class=\"alignnone size-full wp-image-1035235\" src=\"https://yithemes.com/wp-content/uploads/2019/04/01-2.jpg\" alt=\"WordCamp London\" width=\"1000\" height=\"800\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/01-2.jpg 1000w, https://yithemes.com/wp-content/uploads/2019/04/01-2-363x290.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/01-2-300x240.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/01-2-768x614.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/01-2-261x209.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/01-2-311x249.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/01-2-270x216.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p dir=\"ltr\">I had the immense pleasure to represent YITH in London and it was my third time attending London WordCamp. Also, two years ago was the first time that I met up with Ausilia and Alberto. <a href=\"https://yithemes.com/blog/events/wordcamp-london-a-great-experience-and-great-people/\" target=\"_blank\" rel=\"noopener noreferrer\" data-saferedirecturl=\"https://www.google.com/url?q=https://yithemes.com/blog/events/wordcamp-london-a-great-experience-and-great-people/&amp;source=gmail&amp;ust=1554899737827000&amp;usg=AFQjCNHMf_nHW-vvEhdkFRCVjivWEfIIjA\">Read about it here &gt;</a> The event still has the same excitement and buzz as every year with this year’s theme around the London markets. It would also be the first time I was going to give a full-length talk at a WordCamp.</p>\n<figure id=\"attachment_1035236\" aria-describedby=\"caption-attachment-1035236\" style=\"width: 1000px\" class=\"wp-caption alignnone\"><img class=\"wp-image-1035236 size-full\" src=\"https://yithemes.com/wp-content/uploads/2019/04/02-2.jpg\" alt=\"WordCamp London\" width=\"1000\" height=\"800\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/02-2.jpg 1000w, https://yithemes.com/wp-content/uploads/2019/04/02-2-363x290.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/02-2-300x240.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/02-2-768x614.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/02-2-261x209.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/02-2-311x249.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/02-2-270x216.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /><figcaption id=\"caption-attachment-1035236\" class=\"wp-caption-text\">London Metropolitan University building &#8211; Ronald at the YITH stand in the Grad Building &#8211; Opening remarks</figcaption></figure>\n<h2 dir=\"ltr\">Day one &#8211; Saturday 6 April 2019</h2>\n<p dir=\"ltr\">An early 6:30 start meant that I could take my time in setting up the YITH sponsor table in the graduate centre at the Metropolitan University. I was not the first to arrive, as the organisers were in full swing putting up posters and setting up the registration desk. What a commitment from the organising team, as I found out some were still setting up and testing the video streams at 1 am that morning! Coffee was my next thing to sort out at this time of the day. This year&#8217;s swag included a water bottle and a reusable insulated coffee cup. A really nice thing as everyone is much more conscious about the environment and sustainability.</p>\n<p dir=\"ltr\">The next three hours went by very quickly and before I realised I was surrounded by WordCamp attendees asking questions, collecting swag including the hottest item at the event, the ‘Keep Calm and Clear Cache’ t-shirt.</p>\n<p dir=\"ltr\">I was pleasantly surprised by the number of existing customers coming over and simply saying: ‘I use a couple of your plugins and they are great and easy to use’. That is just so lovely to hear, but I do admit I was also enjoying the more challenging questions… like for example: ‘what should I use to have a <a href=\"https://yithemes.com/themes/plugins/yith-woocommerce-featured-audio-video-content/\" target=\"_blank\" rel=\"noopener noreferrer\" data-saferedirecturl=\"https://www.google.com/url?q=https://yithemes.com/themes/plugins/yith-woocommerce-featured-audio-video-content/&amp;source=gmail&amp;ust=1554899737827000&amp;usg=AFQjCNGEsSLWhWt3M9pvhKumj3TsjgTZ7g\">video playing in the gallery </a>of product images?’</p>\n<p dir=\"ltr\">The day passed very quickly and I soon found myself in the ‘rocket’. This part of the building is were the bar and track A is located. With a couple of hours to spare, I met up with some old friends and chatted over a few beverages. The main conference room was changed over to accommodate the hundreds of attendees soon to enjoy a delicious filled baked potato with various types of chillies. After dinner, the beers were calling though I chose to get back to the hotel for a good night sleep as the next day would be a big one…</p>\n<figure id=\"attachment_1035978\" aria-describedby=\"caption-attachment-1035978\" style=\"width: 1000px\" class=\"wp-caption alignnone\"><img class=\"wp-image-1035978 size-full\" src=\"https://yithemes.com/wp-content/uploads/2019/04/03-bis.jpg\" alt=\"\" width=\"1000\" height=\"809\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/03-bis.jpg 1000w, https://yithemes.com/wp-content/uploads/2019/04/03-bis-363x294.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/03-bis-300x243.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/03-bis-768x621.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/03-bis-261x211.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/03-bis-311x252.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/03-bis-270x218.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /><figcaption id=\"caption-attachment-1035978\" class=\"wp-caption-text\">Ready to receive the hundreds of attendees &#8211; A busy Saturday morning at WordCamp London 2019 and our little helper Arda</figcaption></figure>\n<h2 dir=\"ltr\">Day two &#8211; Sunday 7 April 2019</h2>\n<p dir=\"ltr\">Good Morning London! It was a nice and quiet early start but I had some revision to do. Before I tucked into a full English breakfast, I went over my talk, again. I love early mornings in a busy city as you see everyone setting up and travelling to start a new day of work or pleasure. My first priority was to get myself sorted in track B for my talk: ‘Are you ready to publish? The afterlife…’ I was talking about the value of blogs and news for small and medium businesses and that you should consider whether your efforts actually pay off. In the complex world of SEO, publishing, analytics and setting up goals, there is so much to consider. My main aim was to set off a spark to those that attended.</p>\n<p dir=\"ltr\">I received amazing feedback from those in the room the ones outside, including from Team Yoast and even those who watched the live stream from the hotel room… it was Sunday morning after all.</p>\n<p dir=\"ltr\">My helpers took charge of the YITH sponsor table and I was delighted to see a small crowd gathering around it again… While other talks were taking place I managed to finally chat to some of the other sponsors in my area. Team Yoast, A2 Hosting, Weglot, Jupiter X, WooCommerce, Jetpack, Bluehost and WP&amp;UP (a mental health charity dedicated to WordPress users) It is such a great community and we all supported each other over the two days whether it was to get some coffee or take turns going for lunch or just general feeling great being here and doing what we do.</p>\n<figure id=\"attachment_1035238\" aria-describedby=\"caption-attachment-1035238\" style=\"width: 1000px\" class=\"wp-caption alignnone\"><img class=\"wp-image-1035238 size-full\" src=\"https://yithemes.com/wp-content/uploads/2019/04/04-2.jpg\" alt=\"Ready to receive the hundreds of attendees  - A busy Saturday morning at WordCamp London 2019\" width=\"1000\" height=\"454\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/04-2.jpg 1000w, https://yithemes.com/wp-content/uploads/2019/04/04-2-363x165.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/04-2-300x136.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/04-2-768x349.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/04-2-261x118.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/04-2-311x141.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/04-2-270x123.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /><figcaption id=\"caption-attachment-1035238\" class=\"wp-caption-text\">Ronald speaking at WordCamp London (photo credit: Elliott richmond) &#8211; Jupiter X with Maziar and Babek</figcaption></figure>\n<figure id=\"attachment_1035239\" aria-describedby=\"caption-attachment-1035239\" style=\"width: 1000px\" class=\"wp-caption alignnone\"><img class=\"wp-image-1035239 size-full\" src=\"https://yithemes.com/wp-content/uploads/2019/04/05-2.jpg\" alt=\"WordCamp London 2019\" width=\"1000\" height=\"454\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/05-2.jpg 1000w, https://yithemes.com/wp-content/uploads/2019/04/05-2-363x165.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/05-2-300x136.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/05-2-768x349.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/05-2-261x118.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/05-2-311x141.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/05-2-270x123.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /><figcaption id=\"caption-attachment-1035239\" class=\"wp-caption-text\">Siobhan and Jimmy from team Yoast &#8211; Ivan from Siteground and Ronald</figcaption></figure>\n<p>&nbsp;</p>\n<h2 dir=\"ltr\">The afterthoughts</h2>\n<p dir=\"ltr\">Organising a WordCamp is one of the most rewarding things to do but it really takes a lot of time and energy. I, myself am in the process of organising the second Bristol WordCamp and YITH will soon announce more details on a WordCamp in Catania. I want to thank each individual organiser, volunteer, university staff member, caterer for their efforts to make this a super exciting and smoothly run event. Dan Maby and Barbara Saul, in particular, deserve a special mention. They were the leads for this year’s WordCamp London and at the closing remarks, there was already talk about 2020…. I mean, what energy these two have and how truly inspiring to the rest of the WordPress community.</p>\n<p dir=\"ltr\">For YITH it has been very humbling too, to have taken part again in this event. But most importantly it is because of you, our supporters, users, club members that we love what we are doing. Thank you for coming over to see us and just one last thing… ‘Keep Calm and Clear your Cache’</p>\n<figure id=\"attachment_1035240\" aria-describedby=\"caption-attachment-1035240\" style=\"width: 1000px\" class=\"wp-caption alignnone\"><img class=\"wp-image-1035240 size-full\" src=\"https://yithemes.com/wp-content/uploads/2019/04/06-2.jpg\" alt=\"WordCamp London 2019\" width=\"1000\" height=\"367\" srcset=\"https://yithemes.com/wp-content/uploads/2019/04/06-2.jpg 1000w, https://yithemes.com/wp-content/uploads/2019/04/06-2-363x133.jpg 363w, https://yithemes.com/wp-content/uploads/2019/04/06-2-300x110.jpg 300w, https://yithemes.com/wp-content/uploads/2019/04/06-2-768x282.jpg 768w, https://yithemes.com/wp-content/uploads/2019/04/06-2-261x96.jpg 261w, https://yithemes.com/wp-content/uploads/2019/04/06-2-311x114.jpg 311w, https://yithemes.com/wp-content/uploads/2019/04/06-2-270x99.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /><figcaption id=\"caption-attachment-1035240\" class=\"wp-caption-text\">Dan Maby doing the closing remarks &#8211; YITH proudly sponsored this year’s WordCamp London</figcaption></figure>\n<h2 dir=\"ltr\">Where to see us next?</h2>\n<p dir=\"ltr\">Our next WordCamps will be in:</p>\n<ul>\n<li dir=\"ltr\">Bilbao &#8211; Spain &#8211; on the 27-28 April <a href=\"https://2019.bilbao.wordcamp.org/\" target=\"_blank\" rel=\"nofollow noopener noreferrer\">https://2019.bilbao.wordcamp.org/</a></li>\n<li dir=\"ltr\">Bari &#8211; Italy &#8211; on 17-18 May <a href=\"https://2019.bari.wordcamp.org/\" target=\"_blank\" rel=\"nofollow noopener noreferrer\">https://2019.bari.wordcamp.org/</a></li>\n<li>Bristol &#8211; United Kingdom &#8211; on the 17-19 May &#8211; <a href=\"https://2019.bristol.wordcamp.org/\" target=\"_blank\" rel=\"nofollow noopener noreferrer\" data-saferedirecturl=\"https://www.google.com/url?q=https://2019.bristol.wordcamp.org/&amp;source=gmail&amp;ust=1554899737828000&amp;usg=AFQjCNFB8wPjTWNh9UfyVqDZ-M2HM3yuzg\">https://2019.bristol.wordcamp.<wbr />org/</a></li>\n<li dir=\"ltr\">Irùn &#8211; Spain &#8211; on the 1-2 June &#8211; <a href=\"https://2019.irun.wordcamp.org/\" target=\"_blank\" rel=\"nofollow noopener noreferrer\">https://2019.irun.wordcamp.org/</a></li>\n<li dir=\"ltr\">WORDCAMP EUROPE! Berlin &#8211; Germany &#8211; on the 20-22 June <a href=\"https://2019.europe.wordcamp.org/\" target=\"_blank\" rel=\"nofollow noopener noreferrer\">https://2019.europe.wordcamp.org/</a></li>\n</ul>\n<p>&nbsp;</p>\n<p>Ronald Gijsel</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://yithemes.com/blog/events/keep-calm-and-clear-your-cache-wordcamp-london-2019/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"WordCamp Granada 2018 – Perfectly organised from A to Z\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"https://yithemes.com/blog/events/wordcamp-granada-2018-perfectly-organised-from-a-to-z/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:95:\"https://yithemes.com/blog/events/wordcamp-granada-2018-perfectly-organised-from-a-to-z/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 24 Dec 2018 13:54:02 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://yithemes.com/?p=1007221\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:327:\"Granada´s very first WordCamp, and we were there! It got of to a great start on the contributor day, which was held in the University of Granada, where we had our first get- together and introduction to the upcoming event. Afterwards we took our chance to contribute to the WordPress community and joined the Support [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"YITH Support Team\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5714:\"<p><span style=\"font-weight: 400;\">Granada´s very first WordCamp, and we were there! It got of to a great start on the contributor day, which was held in the University of Granada, where we had our first get- together and introduction to the upcoming event.</span></p>\n<p><span style=\"font-weight: 400;\">Afterwards we took our chance to contribute to the WordPress community and joined the Support and Polyglots tables to have a productive yet enjoyable afternoon!</span></p>\n<p><span style=\"font-weight: 400;\"><strong>The venue was perfect for the contributor day</strong> and we could already tell that just like the first day, every part of the event was going to be organised well up until the smallest details.</span></p>\n<p><img class=\"alignnone size-full wp-image-1007222\" src=\"https://yithemes.com/wp-content/uploads/2018/12/02.jpg\" alt=\"WordCamp Granada 2018\" width=\"1000\" height=\"400\" srcset=\"https://yithemes.com/wp-content/uploads/2018/12/02.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/12/02-363x145.jpg 363w, https://yithemes.com/wp-content/uploads/2018/12/02-300x120.jpg 300w, https://yithemes.com/wp-content/uploads/2018/12/02-768x307.jpg 768w, https://yithemes.com/wp-content/uploads/2018/12/02-261x104.jpg 261w, https://yithemes.com/wp-content/uploads/2018/12/02-311x124.jpg 311w, https://yithemes.com/wp-content/uploads/2018/12/02-270x108.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400;\">In the evening we were invited to the dinner for sponsors and speakers, which was in the famous neighbourhood of Albaicín, which makes you feel like you are walking around in a fairy tale or old movie with its narrow streets and amazing architecture and of course the <strong>Alhambra! Which</strong> we were very surprised to find out that the dinner had immediate views up on. </span></p>\n<p><img class=\"alignnone size-full wp-image-1007223\" src=\"https://yithemes.com/wp-content/uploads/2018/12/01.jpg\" alt=\"WordCamp Granada 2018\" width=\"1000\" height=\"400\" srcset=\"https://yithemes.com/wp-content/uploads/2018/12/01.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/12/01-363x145.jpg 363w, https://yithemes.com/wp-content/uploads/2018/12/01-300x120.jpg 300w, https://yithemes.com/wp-content/uploads/2018/12/01-768x307.jpg 768w, https://yithemes.com/wp-content/uploads/2018/12/01-261x104.jpg 261w, https://yithemes.com/wp-content/uploads/2018/12/01-311x124.jpg 311w, https://yithemes.com/wp-content/uploads/2018/12/01-270x108.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400;\">On the next day we found our ways to the Palacio de Congresos of Granada, <strong>where a great team of volunteers was ready to help us with whatever we needed</strong>, after a quick set-up we were ready for the doors to open!</span></p>\n<p><img class=\"alignnone size-full wp-image-1007224\" src=\"https://yithemes.com/wp-content/uploads/2018/12/03.jpg\" alt=\"WordCamp Granada 2018\" width=\"1000\" height=\"400\" srcset=\"https://yithemes.com/wp-content/uploads/2018/12/03.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/12/03-363x145.jpg 363w, https://yithemes.com/wp-content/uploads/2018/12/03-300x120.jpg 300w, https://yithemes.com/wp-content/uploads/2018/12/03-768x307.jpg 768w, https://yithemes.com/wp-content/uploads/2018/12/03-261x104.jpg 261w, https://yithemes.com/wp-content/uploads/2018/12/03-311x124.jpg 311w, https://yithemes.com/wp-content/uploads/2018/12/03-270x108.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400;\">We were all very heartwarmed by the song about code from Fran Torres.</span></p>\n<p><strong>And after the first talks started and during the networking and breaks our hilarious shirts went out very fast!</strong> Everyone loved them, probably because of the reletable phrase <strong>“It works on my PC”</strong> . Haven&#8217;t we all been there?!</p>\n<p><span style=\"font-weight: 400;\">We saw many familiar faces but also had the chance to meet and have interesting chats with attendees from all around the world, from Spain to India!</span></p>\n<p><span style=\"font-weight: 400;\">The big smiles are not only thanks to the productive time spend listening and learning at the talks and workshops, I am sure this also had something to do with the provided lunch that included paella among various delicious treats! <strong>And the fact that the day was very well organised in this amazing location with a great turnout, in total almost 400 people!</strong></span></p>\n<p><span style=\"font-weight: 400;\">We would like to thank the organisation for setting up this spectacular weekend! And a big thumbs up to all volunteers, We appreciated all of your effort and care throughout the WordCamp and it would not have been possible without you! </span></p>\n<p><span style=\"font-weight: 400;\">Both the event and city have made a great impression on us, and we will surely come back for a longer visit in the near future! </span></p>\n<p><img class=\"alignnone size-full wp-image-1007225\" src=\"https://yithemes.com/wp-content/uploads/2018/12/04.jpg\" alt=\"WordCamp Granada 2018\" width=\"1000\" height=\"400\" srcset=\"https://yithemes.com/wp-content/uploads/2018/12/04.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/12/04-363x145.jpg 363w, https://yithemes.com/wp-content/uploads/2018/12/04-300x120.jpg 300w, https://yithemes.com/wp-content/uploads/2018/12/04-768x307.jpg 768w, https://yithemes.com/wp-content/uploads/2018/12/04-261x104.jpg 261w, https://yithemes.com/wp-content/uploads/2018/12/04-311x124.jpg 311w, https://yithemes.com/wp-content/uploads/2018/12/04-270x108.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p>&nbsp;</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://yithemes.com/blog/events/wordcamp-granada-2018-perfectly-organised-from-a-to-z/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:38:\"WordPress 5.0 under the Christmas tree\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"https://yithemes.com/blog/yit-news/wordpress-5-0-under-the-christmas-tree/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://yithemes.com/blog/yit-news/wordpress-5-0-under-the-christmas-tree/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 05 Dec 2018 15:41:54 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"YITH News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://yithemes.com/?p=1002420\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:313:\"Yesterday we have learned that WordPress 5.0 will be released on December 6th (tomorrow). This news was a surprise to us as we all thought it would have been released after the Christmas holidays. Given the short notice, we would like to give you some advice and make you consider a few things. We would [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Marco Salvo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2630:\"<p>Yesterday we have learned that WordPress 5.0 will be released on December 6th (tomorrow).</p>\n<p>This news was a surprise to us as we all thought it would have been released after the Christmas holidays.</p>\n<p>Given the short notice, we would like to give you some advice and make you consider a few things. We would also like to specify that YITH is ready for this new version.</p>\n<p>Before updating to WordPress 5.0, we want you to spend two minutes thinking about the future of your business and ask yourself some questions.</p>\n<h2>Do you think this is the right moment to update to WordPress 5.0?</h2>\n<p>December is a month when everyone is weighed down with work due to the upcoming holidays. All the stores are crowded and also online shops register this month as the most profitable of the year.</p>\n<p>Consider that in January, when holidays will be over, you can update calmly. Moreover, the patches already scheduled will be released and your system will be more stable.</p>\n<h2>Will your site work with Gutenberg?</h2>\n<p>WordPress 5.0 will integrate Gutenberg. Gutenberg is a new text editor with higher performances that will revolutionize the way of writing in WordPress. If you still don&#8217;t know about Gutenberg, I suggest referring to <a href=\"https://wordpress.org/gutenberg/\" target=\"_blank\" rel=\"noopener\">this</a>.</p>\n<p>YITH plugins are almost all ready and many have been already released with support to the new version, but since not all of them are ready, it is important for you to know whether those you are using can support the update.</p>\n<p>If you are using other plugins in addition to YITH ones that integrate with Gutenberg, please check (by testing them or consulting the plugin documentation) they are ready or at least that they won&#8217;t cause fatal errors. Otherwise, I suggest installing and activating the plugin <a href=\"https://wordpress.org/plugins/classic-editor/\" target=\"_blank\" rel=\"noopener\">Classic Editor</a> before the update.</p>\n<p>Just to be clear, we love Gutenberg and YITH plugins have integrated blocks to use their own shortcodes. We are ready! Yet, we think this version will be even more stable and safer in January.</p>\n<p>Therefore, our advice is the following: <strong>slow and steady wins the race</strong>.</p>\n<h2>If you still want to update to WordPress 5.0</h2>\n<p>Before updating, make a backup. If you have a staging environment, we recommend testing there the new version first.</p>\n<p>If you don&#8217;t have any and your site is fully active and essential for your business, create one. This advice is valid also for any major release.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"https://yithemes.com/blog/yit-news/wordpress-5-0-under-the-christmas-tree/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"WordCamp Barcelona 2018 – Impressive is not enough!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:82:\"https://yithemes.com/blog/events/wordcamp-barcelona-2018-impressive-is-not-enough/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://yithemes.com/blog/events/wordcamp-barcelona-2018-impressive-is-not-enough/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 27 Nov 2018 09:18:15 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://yithemes.com/?p=998071\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:342:\"We didn’t miss our appointment in Barcelona. WordCamp Barcelona got back after almost 2 years (there wasn’t WordCamp in 2017) with one of the most powerful Contributor Day we have seen and the event was at an impressive and precious venue (Historic Building of the University of Barcelona). Really a WordCamp worthy of its city. [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"YITH Support Team\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:6963:\"<p><span style=\"font-weight: 400\">We didn’t miss our appointment in Barcelona. <strong>WordCamp Barcelona got back after almost 2 years</strong> (there wasn’t WordCamp in 2017) with one of the most powerful Contributor Day we have seen and the event was at an impressive and precious venue (Historic Building of the University of Barcelona). Really a WordCamp worthy of its city.</span></p>\n<p><span style=\"font-weight: 400\">On Friday, we assisted to the Contributor Day in the <strong>Movistar Centre</strong>, right in the heart of Barcelona.</span></p>\n<p><img class=\"alignnone size-full wp-image-998075\" src=\"https://yithemes.com/wp-content/uploads/2018/11/02.jpg\" alt=\"\" width=\"1000\" height=\"454\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/02.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/02-363x165.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/02-300x136.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/02-768x349.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/02-261x118.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/02-311x141.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/02-270x123.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">This great and modern building had all the necessary resources to cover such an event.</span></p>\n<p><span style=\"font-weight: 400\">Also, we’ve got great sights to Plaza Catalunya.</span></p>\n<p><img class=\"alignnone size-full wp-image-998076\" src=\"https://yithemes.com/wp-content/uploads/2018/11/03.jpg\" alt=\"\" width=\"1000\" height=\"454\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/03.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/03-363x165.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/03-300x136.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/03-768x349.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/03-261x118.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/03-311x141.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/03-270x123.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">Something to highlight was the organization and coordination of the attendees. Quickly, the tables were assigned between the different categories to contribute.</span></p>\n<p><img class=\"alignnone size-full wp-image-998077\" src=\"https://yithemes.com/wp-content/uploads/2018/11/04.jpg\" alt=\"\" width=\"1000\" height=\"454\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/04.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/04-363x165.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/04-300x136.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/04-768x349.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/04-261x118.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/04-311x141.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/04-270x123.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">The next day, we went to the <strong>Historic Building of the University of Barcelona</strong> to assist the WordCamp. <strong>This WordCamp had over 300 attendants</strong>. Everything took place on the 1st floor. Our stand was next to the Sala Paranimf’s entry. The Sala Paranimf is an enormous and stunning catholic-style hall.</span></p>\n<p><img class=\"alignnone size-full wp-image-998078\" src=\"https://yithemes.com/wp-content/uploads/2018/11/05.jpg\" alt=\"\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/05.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/05-363x182.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/05-300x150.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/05-768x384.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/05-261x131.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/05-311x156.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/05-270x135.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">We released a new T-Shirt model which ran out very soon! (as always :P) The attendees really loved it, they took them off our hands!!</span></p>\n<p><img class=\"alignnone size-full wp-image-998079\" src=\"https://yithemes.com/wp-content/uploads/2018/11/06.jpg\" alt=\"\" width=\"1000\" height=\"454\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/06.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/06-363x165.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/06-300x136.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/06-768x349.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/06-261x118.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/06-311x141.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/06-270x123.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">Without hesitation, we can say that we had a good time on this WordCamp.</span></p>\n<p><span style=\"font-weight: 400\">Of course, <strong>we want to thank the WordCamp organization</strong>, which made a great effort and managed everything successfully. We receive the best possible treatment.</span></p>\n<p><img class=\"alignnone size-full wp-image-998080\" src=\"https://yithemes.com/wp-content/uploads/2018/11/07.jpg\" alt=\"\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/07.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/07-363x182.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/07-300x150.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/07-768x384.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/07-261x131.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/07-311x156.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/07-270x135.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">During the WordCamp weekend, we have time to visit many beautiful places in Barcelona, like “La Sagrada Familia” of Gaudí, Las Ramblas, the Barceloneta beach or the amazing Parc Güell among other wonderful locations in the city. </span></p>\n<p><img class=\"alignnone size-full wp-image-998081\" src=\"https://yithemes.com/wp-content/uploads/2018/11/08.jpg\" alt=\"\" width=\"1000\" height=\"360\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/08.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/08-363x131.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/08-300x108.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/08-768x276.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/08-261x94.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/08-311x112.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/08-270x97.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"https://yithemes.com/blog/events/wordcamp-barcelona-2018-impressive-is-not-enough/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"Black Friday 30% off – Details\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:63:\"https://yithemes.com/blog/yit-news/black-friday-30-off-details/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://yithemes.com/blog/yit-news/black-friday-30-off-details/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 23 Nov 2018 14:55:39 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"YITH News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://yithemes.com/?p=997134\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:319:\"What is this Black Friday offer about? The offer is a 30% discount on everything, yes!, every product that you can find here on YITH for the whole Black Friday weekend, so until Sunday 25th November. It applies also to the Club Subscription (both annual and monthly plan). The prices on the product pages will [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"Francesco\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:1621:\"<p>What is this <strong>Black Friday</strong> offer about?</p>\n<p>The offer is a <strong>30% discount on everything</strong>, yes!, every product that you can find here on YITH for the whole Black Friday weekend, so until Sunday 25th November.</p>\n<p>It applies also to the Club Subscription (both annual and monthly plan).</p>\n<p>The prices on the product pages will not change, but you will see the discount in the cart.</p>\n<p>It will look like this:</p>\n<p><img class=\"aligncenter size-full wp-image-997275\" src=\"https://yithemes.com/wp-content/uploads/2018/11/screen.jpg\" alt=\"\" width=\"1000\" height=\"672\" srcset=\"https://yithemes.com/wp-content/uploads/2018/11/screen.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/11/screen-363x244.jpg 363w, https://yithemes.com/wp-content/uploads/2018/11/screen-300x202.jpg 300w, https://yithemes.com/wp-content/uploads/2018/11/screen-768x516.jpg 768w, https://yithemes.com/wp-content/uploads/2018/11/screen-261x175.jpg 261w, https://yithemes.com/wp-content/uploads/2018/11/screen-311x209.jpg 311w, https://yithemes.com/wp-content/uploads/2018/11/screen-270x181.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p>&nbsp;</p>\n<p>Consider also that the Black Friday offer cannot be combined with other coupons, so, make sure you use the one that is most advantageous for you!</p>\n<p>And, please, do not hesitate to contact us through our <strong>live chat</strong> if you have any doubts, we&#8217;ll be happy to help!</p>\n<p>Click <a href=\"https://yithemes.com/product-category/plugins?orderby=popularity\"><strong>here</strong></a> to continue shopping now!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://yithemes.com/blog/yit-news/black-friday-30-off-details/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"First WordCamp Verona: a great success in every aspect!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"https://yithemes.com/blog/events/first-wordcamp-veronaa-great-success-in-every-aspect/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:94:\"https://yithemes.com/blog/events/first-wordcamp-veronaa-great-success-in-every-aspect/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 26 Oct 2018 14:30:29 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://yithemes.com/?p=987146\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:333:\"During the after party at WordCamp Verona, we were asked if at YITH we fight for taking part in WordCamps. Well, we don’t get into fights, but, personally speaking, as time goes by,  our passion for WordPress events grows bigger that taking part in them becomes like an obsession, we get more and more WordPress-addicted [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"YITH Support Team\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5894:\"<p><span style=\"font-weight: 400\">During the after party at WordCamp Verona, we were asked if at YITH we fight for taking part in WordCamps. Well, we don’t get into fights, but, personally speaking, as time goes by, <strong> our passion for WordPress events grows bigger that taking part in them becomes like an obsession</strong>, we get more and more WordPress-addicted every day and we like this!</span></p>\n<p><span style=\"font-weight: 400\">Is it the attendees’ enthusiasm? Or the organisers’? Or is it the passionate and tireless contribute of the volunteers that makes everything so motivating, exciting and fun?</span><span style=\"font-weight: 400\"><br />\n</span><span style=\"font-weight: 400\">At YITH, we don’t get into fights, but, yes, we have to leave space to others, sort of taking turns to leave for WordCamp events, as everyone wants to!</span></p>\n<p><span style=\"font-weight: 400\">Fortunately, WordCamps are increasing in number and we now have more opportunities. Moreover, the organisation is improving as well, thanks to the experience of others in the community. </span></p>\n<p><span style=\"font-weight: 400\">This is what <strong>makes the community even more precious and its growth faster and faster</strong>: you learn from others’ experiences, from a shared knowledge, not only for what concerns contributing to the WordPress open source project but also for what concerns the organisation of local and international events.</span></p>\n<p><span style=\"font-weight: 400\">It’s like being part of a one big body that grows day after day thanks to the boundless enthusiasm of all <strong>WordPress lovers</strong>!</span></p>\n<p><span style=\"font-weight: 400\">This is why we would like to say one more word about <strong>WordCamp Verona</strong>, the first WordPress event in the town that learned from others’ experiences and managed to organise a solid event, where the feeling of being part of a family-like community could be strongly felt.</span></p>\n<p><img class=\"alignnone size-full wp-image-987147\" src=\"https://yithemes.com/wp-content/uploads/2018/10/01.jpg\" alt=\"WordCamp Verona - YITH Crew\" width=\"1000\" height=\"500\" /></p>\n<p><img class=\"alignnone size-full wp-image-987148\" src=\"https://yithemes.com/wp-content/uploads/2018/10/02-1.jpg\" alt=\"WordCamp Verona - YITH and Friends\" width=\"1000\" height=\"500\" /></p>\n<p><span style=\"font-weight: 400\">The organization was excellent, attentive and careful. 225 the attendees and an outstanding participation to the Contributor Day: <strong>over 80 contributors worked hard</strong> and actively during the day, it was noteworthy.</span></p>\n<p><img class=\"alignnone size-full wp-image-987152\" src=\"https://yithemes.com/wp-content/uploads/2018/10/03-1.jpg\" alt=\"WordCamp Verona - YITH swag\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/03-1.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/03-1-363x182.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/03-1-300x150.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/03-1-768x384.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/03-1-261x131.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/03-1-311x156.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/03-1-270x135.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><img class=\"alignnone size-full wp-image-987153\" src=\"https://yithemes.com/wp-content/uploads/2018/10/04-1.jpg\" alt=\"WordCamp Verona - WordCamp volunteers\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/04-1.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/04-1-363x182.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/04-1-300x150.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/04-1-768x384.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/04-1-261x131.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/04-1-311x156.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/04-1-270x135.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">What about the speakers? About half of them were women, and it is not always easy to record such a percentage, meaning also that the <strong>women’s share in WordPress is gradually increasing</strong>.</span><span style=\"font-weight: 400\"><br />\n</span><span style=\"font-weight: 400\">And then, all the talks were successful: as members of the community this makes us proud, especially if we think that almost all the speakers (11 out of 12) were talking for the first time in a WordCamp. We can’t help being proud of all this!</span></p>\n<p><span style=\"font-weight: 400\">Moving then to the </span><i><span style=\"font-weight: 400\">social</span></i><span style=\"font-weight: 400\"> side of the event, well, everyone was warmly welcomed, <strong>it felt like being part of a big family or a merry gang!</strong> Maybe because of the number of people (not huge), but certainly thanks to the organisers who made all this possible. There was such a friendly atmosphere that made all of us feel so close as ever, professionally and personally speaking.</span></p>\n<p><img class=\"alignnone size-full wp-image-987154\" src=\"https://yithemes.com/wp-content/uploads/2018/10/05-1.jpg\" alt=\"WordCamp Verona\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/05-1.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/05-1-363x182.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/05-1-300x150.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/05-1-768x384.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/05-1-261x131.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/05-1-311x156.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/05-1-270x135.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"https://yithemes.com/blog/events/first-wordcamp-veronaa-great-success-in-every-aspect/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"1st WordCamp at Pontevedra: YITH was there!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"https://yithemes.com/blog/events/1st-wordcamp-at-pontevedra-yith-was-there/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://yithemes.com/blog/events/1st-wordcamp-at-pontevedra-yith-was-there/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 02 Oct 2018 10:00:37 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://yithemes.com/?p=979070\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:342:\"We have attended the fantastic WordCamp of Pontevedra, which has exceeded our expectations. With nearly 200 participants in its first year, they became one of the most important WordCamps in the Spanish scene. The event was held at the Faculty of Social Sciences and Communication of the University of Vigo, located in the Campus of [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"YITH Support Team\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:7109:\"<p>We have attended the fantastic <strong>WordCamp of Pontevedra</strong>, which has exceeded our expectations. With nearly 200 participants in its first year, they became <strong>one of the most important WordCamps in the Spanish</strong> scene.</p>\n<p>The event was held at the <strong>Faculty of Social Sciences and Communication of the University of Vigo</strong>, located in the Campus of Pontevedra, a privileged place to host an event in where it is intended to share all the potential our WordPress community has.</p>\n<p><img class=\"alignnone size-full wp-image-979071\" src=\"https://yithemes.com/wp-content/uploads/2018/10/02.jpg\" alt=\"\" width=\"1000\" height=\"432\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/02.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/02-363x157.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/02-300x130.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/02-768x332.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/02-261x113.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/02-311x134.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/02-270x117.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">The WordCamp had a great variety of presentations, which made it difficult to decide which ones to attend, thank goodness we have WordPress TV to see those we have missed!</span></p>\n<p><span style=\"font-weight: 400\">Another thing we would not want to have missed are the stands of the sponsors, who gave very cool merchandise to attendees such as shirts, socks, stickers and many more.</span></p>\n<p>Among the speakers at the event was <strong>Sara Presenti</strong>, UX designer of YITH, <a href=\"https://wordpress.tv/2018/09/23/sara-presenti-la-importancia-de-la-atencion-al-cliente-en-un-e-commerce/\" target=\"_blank\" rel=\"noopener\">who spoke about the importance of customer service in an e-commerce</a>. She gave us some advice on how to keep our old customers happy and at the same time manage to attract new ones, trying to keep everyone satisfied.</p>\n<p><img class=\"alignnone size-full wp-image-979220\" src=\"https://yithemes.com/wp-content/uploads/2018/10/sara-presenti.jpg\" alt=\"Sara Presenti\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/sara-presenti.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/sara-presenti-363x182.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/sara-presenti-300x150.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/sara-presenti-768x384.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/sara-presenti-261x131.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/sara-presenti-311x156.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/sara-presenti-270x135.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">One of the funniest activities was the <strong>game of cards made by the organization</strong>, with which it was intended to make the stay of the WordCamp participants more fun and to bring them closer to the sponsors and speakers, since they had to be encouraged to ask for their personal letters for the collection. Although we all know that the most important one was the José Luis card!</span></p>\n<p><span style=\"font-weight: 400\">The final activity of a magnificent WordCamp day, was the famous <strong>‘Pulpo a La Gallega’</strong>, which we were invited too by our Dinahosting friends and which made us enjoy the beauty of the Galician gastronomy.</span></p>\n<p><img class=\"alignnone size-full wp-image-979072\" src=\"https://yithemes.com/wp-content/uploads/2018/10/03.jpg\" alt=\"WC Pontevedra food\" width=\"1000\" height=\"432\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/03.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/03-363x157.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/03-300x130.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/03-768x332.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/03-261x113.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/03-311x134.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/03-270x117.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\"><strong>On Sunday the Contributor Day was held,</strong> which had a great turn up by the attendees of the event, willing to be an active part of the WordPress community.</span></p>\n<p><img class=\"alignnone size-full wp-image-979073\" src=\"https://yithemes.com/wp-content/uploads/2018/10/04.jpg\" alt=\"WC Pontevedra Contributor day\" width=\"1000\" height=\"432\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/04.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/04-363x157.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/04-300x130.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/04-768x332.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/04-261x113.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/04-311x134.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/04-270x117.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">We would like to thank the entire WordCamp organization, which made it possible for everything to run successfully.</span></p>\n<p><img class=\"alignnone size-full wp-image-979074\" src=\"https://yithemes.com/wp-content/uploads/2018/10/05.jpg\" alt=\"WC Pontevedra volunteers\" width=\"1000\" height=\"432\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/05.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/05-363x157.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/05-300x130.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/05-768x332.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/05-261x113.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/05-311x134.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/05-270x117.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">And at the end of our journey through these beautiful Galician lands, <strong>we took a nice walk through the city of Pontevedra</strong>, where we could enjoy its historical monuments and buildings, such as the incredible Church of the Pilgrim or the Church of San Francisco.</span></p>\n<p><img class=\"alignnone size-full wp-image-979077\" src=\"https://yithemes.com/wp-content/uploads/2018/10/07.jpg\" alt=\"YITH team at Pontevedra\" width=\"1000\" height=\"432\" srcset=\"https://yithemes.com/wp-content/uploads/2018/10/07.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/10/07-363x157.jpg 363w, https://yithemes.com/wp-content/uploads/2018/10/07-300x130.jpg 300w, https://yithemes.com/wp-content/uploads/2018/10/07-768x332.jpg 768w, https://yithemes.com/wp-content/uploads/2018/10/07-261x113.jpg 261w, https://yithemes.com/wp-content/uploads/2018/10/07-311x134.jpg 311w, https://yithemes.com/wp-content/uploads/2018/10/07-270x117.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p>&nbsp;</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:80:\"https://yithemes.com/blog/events/1st-wordcamp-at-pontevedra-yith-was-there/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"The great WordPress event in the Eternal City: WordCamp Rome 2018\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"https://yithemes.com/blog/events/the-great-wordpress-event-in-the-eternal-city-wordcamp-rome-2018/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:106:\"https://yithemes.com/blog/events/the-great-wordpress-event-in-the-eternal-city-wordcamp-rome-2018/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 27 Sep 2018 13:23:56 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://yithemes.com/?p=977610\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:300:\"Also this year we took part in WordCamp Roma 2018, in the Caput Mundi city. Happy we were part of it during the first edition last year, we didn&#8217;t want to miss this one! Just like any major WordCamp, the Contributor Day struck up the band: we went to Luiss EnLabs offices where we had [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"YITH Support Team\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5665:\"<p><span style=\"font-weight: 400\">Also this year we took part in <strong>WordCamp Roma 2018</strong>, in the Caput Mundi city. </span></p>\n<p><span style=\"font-weight: 400\">Happy we were part of it during the first edition last year, we didn&#8217;t want to miss this one!</span></p>\n<p><span style=\"font-weight: 400\">Just like any major WordCamp, the Contributor Day struck up the band: we went to Luiss EnLabs offices where we had the pleasure to meet old friends and know new ones  belonging to this big WordPress family.</span></p>\n<p><span style=\"font-weight: 400\">We have talked about news related to <strong>Gutenberg</strong>, worked on translations, promoted a new WordCamp in Turin in 2019. </span></p>\n<p><span style=\"font-weight: 400\">So, there is always something to keep yourself busy and to not loaf around. <img src=\"https://s.w.org/images/core/emoji/11.2.0/72x72/1f642.png\" alt=\"🙂\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /></span></p>\n<p><img class=\"alignnone size-full wp-image-977622\" src=\"https://yithemes.com/wp-content/uploads/2018/09/01.jpg\" alt=\"WC Roma 2018 Contributor day\" width=\"1000\" height=\"453\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/01.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/09/01-363x164.jpg 363w, https://yithemes.com/wp-content/uploads/2018/09/01-300x136.jpg 300w, https://yithemes.com/wp-content/uploads/2018/09/01-768x348.jpg 768w, https://yithemes.com/wp-content/uploads/2018/09/01-261x118.jpg 261w, https://yithemes.com/wp-content/uploads/2018/09/01-311x141.jpg 311w, https://yithemes.com/wp-content/uploads/2018/09/01-270x122.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">We are always very happy to <strong>take part in these events as we have the chance to know new people</strong> and finally meet in person those interacting with us usually via email or through our support desk. </span></p>\n<p><span style=\"font-weight: 400\">The main thing we are proud of is when we find out how many good seeds we have planted thanks to your praises for our products and our support service. </span></p>\n<p><img class=\"alignnone size-full wp-image-977623\" src=\"https://yithemes.com/wp-content/uploads/2018/09/02.jpg\" alt=\"WordCamp Rome 2018\" width=\"1000\" height=\"443\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/02.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/09/02-363x161.jpg 363w, https://yithemes.com/wp-content/uploads/2018/09/02-300x133.jpg 300w, https://yithemes.com/wp-content/uploads/2018/09/02-768x340.jpg 768w, https://yithemes.com/wp-content/uploads/2018/09/02-261x116.jpg 261w, https://yithemes.com/wp-content/uploads/2018/09/02-311x138.jpg 311w, https://yithemes.com/wp-content/uploads/2018/09/02-270x120.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">During the event, our CEO <strong>Nando Pappalardo had a speech</strong> about how he succeeded in turning from a freelancer into the founder of <strong>one of the most successful business in the WordPress environment</strong>. In a few words, the <strong>amazing history of YITH!</strong> The speech moved many people in the room. Nando has frequently underlined the importance of time, one of the most precious goods we have in this life and to which we often don&#8217;t give the right value.  </span></p>\n<p><img class=\"alignnone size-full wp-image-977624\" src=\"https://yithemes.com/wp-content/uploads/2018/09/03.jpg\" alt=\"WordCamp Rome 2018\" width=\"1000\" height=\"463\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/03.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/09/03-363x168.jpg 363w, https://yithemes.com/wp-content/uploads/2018/09/03-300x139.jpg 300w, https://yithemes.com/wp-content/uploads/2018/09/03-768x356.jpg 768w, https://yithemes.com/wp-content/uploads/2018/09/03-261x121.jpg 261w, https://yithemes.com/wp-content/uploads/2018/09/03-311x144.jpg 311w, https://yithemes.com/wp-content/uploads/2018/09/03-270x125.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">A special thank you goes to <strong>all the organizers and volunteers</strong> who made this WordCamp possible with their excellent contribution.</span></p>\n<p><span style=\"font-weight: 400\">We are treasuring one thousand positive sensations and lots of energy to invest in our daily job, always ready to improve! </span></p>\n<p><span style=\"font-weight: 400\">Until next time! <img src=\"https://s.w.org/images/core/emoji/11.2.0/72x72/1f642.png\" alt=\"🙂\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /></span></p>\n<p><span style=\"font-weight: 400\">P.S.: About this WordCamp Roma 2018, <strong>we feel like highlighting the delicious lunch,</strong> one of the best of all WordCamps ever <img src=\"https://s.w.org/images/core/emoji/11.2.0/72x72/1f600.png\" alt=\"😀\" class=\"wp-smiley\" style=\"height: 1em; max-height: 1em;\" /></span></p>\n<p><img class=\"alignnone size-full wp-image-977625\" src=\"https://yithemes.com/wp-content/uploads/2018/09/04.jpg\" alt=\"WordCamp Rome 2018\" width=\"1000\" height=\"341\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/04.jpg 1000w, https://yithemes.com/wp-content/uploads/2018/09/04-363x124.jpg 363w, https://yithemes.com/wp-content/uploads/2018/09/04-300x102.jpg 300w, https://yithemes.com/wp-content/uploads/2018/09/04-768x262.jpg 768w, https://yithemes.com/wp-content/uploads/2018/09/04-261x89.jpg 261w, https://yithemes.com/wp-content/uploads/2018/09/04-311x106.jpg 311w, https://yithemes.com/wp-content/uploads/2018/09/04-270x92.jpg 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p>&nbsp;</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:103:\"https://yithemes.com/blog/events/the-great-wordpress-event-in-the-eternal-city-wordcamp-rome-2018/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:61:\"\n		\n		\n				\n				\n		\n				\n\n		\n				\n								\n							\n		\n							\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:5:{s:0:\"\";a:7:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"WordCamp San Jose: what a beatiful experience!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"https://yithemes.com/blog/events/wordcamp-san-jose-what-a-beatiful-experience/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"https://yithemes.com/blog/events/wordcamp-san-jose-what-a-beatiful-experience/#respond\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 17 Sep 2018 13:22:46 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:6:\"Events\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"https://yithemes.com/?p=974231\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:298:\"What if someone tells you: hey, I have a plan for you, go to the San José WordCamp in Costa Rica!! And yes, indeed, it was an amazing experience to join the tika WordPress community from the other side of the Atlantic. They attended us and prepared everything in a way so we could easily [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"YITH Support Team\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:4705:\"<p><span style=\"font-weight: 400\">What if someone tells you: hey, I have a plan for you, go to the San José WordCamp in Costa Rica!!</span></p>\n<p><span style=\"font-weight: 400\">And yes, indeed, <strong>it was an amazing experience to join the tika WordPress community from the other side of the Atlantic</strong>. They attended us and prepared everything in a way so we could easily participate on the WordCamp, this was an excellent point.</span></p>\n<p><span style=\"font-weight: 400\">The event was located on the “Universidad de la Latina de Costa Rica” which allowed to have many young participants from the university to let them know about the potential of our WordPress community.</span></p>\n<p><img class=\"alignnone size-full wp-image-974241\" src=\"https://yithemes.com/wp-content/uploads/2018/09/01.png\" alt=\"WordCamp Costa Rica location\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/01.png 1000w, https://yithemes.com/wp-content/uploads/2018/09/01-363x182.png 363w, https://yithemes.com/wp-content/uploads/2018/09/01-300x150.png 300w, https://yithemes.com/wp-content/uploads/2018/09/01-768x384.png 768w, https://yithemes.com/wp-content/uploads/2018/09/01-261x131.png 261w, https://yithemes.com/wp-content/uploads/2018/09/01-311x156.png 311w, https://yithemes.com/wp-content/uploads/2018/09/01-270x135.png 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">The hall where the sponsors were, was big enough to have everyone together and feel that you could move freely, and also, the three speaker rooms were just in the same hall beside of the sponsors tables so you didn’t feel to be separated when everyone went to listen them.</span></p>\n<p><img class=\"alignnone size-full wp-image-974242\" src=\"https://yithemes.com/wp-content/uploads/2018/09/02.png\" alt=\"\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/02.png 1000w, https://yithemes.com/wp-content/uploads/2018/09/02-363x182.png 363w, https://yithemes.com/wp-content/uploads/2018/09/02-300x150.png 300w, https://yithemes.com/wp-content/uploads/2018/09/02-768x384.png 768w, https://yithemes.com/wp-content/uploads/2018/09/02-261x131.png 261w, https://yithemes.com/wp-content/uploads/2018/09/02-311x156.png 311w, https://yithemes.com/wp-content/uploads/2018/09/02-270x135.png 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p>&nbsp;</p>\n<p><span style=\"font-weight: 400\">There was a <strong>big variety of speakers come from different parts of the world</strong> which gave to the attendants the opportunity to learn and have a good knowledge about the meaning, why and how to use WordPress with a wide point of vision.</span></p>\n<p><span style=\"font-weight: 400\">Something that surprised us was the kid’s camp, <strong>an event created just for kids</strong> where they were showed the procedure of installing a WordPress and created some posts making as if it was a game, so <strong>the youngest ones get along with the community</strong>.</span></p>\n<p><img class=\"alignnone size-full wp-image-974243\" src=\"https://yithemes.com/wp-content/uploads/2018/09/03.png\" alt=\"WordPress community\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/03.png 1000w, https://yithemes.com/wp-content/uploads/2018/09/03-363x182.png 363w, https://yithemes.com/wp-content/uploads/2018/09/03-300x150.png 300w, https://yithemes.com/wp-content/uploads/2018/09/03-768x384.png 768w, https://yithemes.com/wp-content/uploads/2018/09/03-261x131.png 261w, https://yithemes.com/wp-content/uploads/2018/09/03-311x156.png 311w, https://yithemes.com/wp-content/uploads/2018/09/03-270x135.png 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p><span style=\"font-weight: 400\">Well, of course, we profited from going to the WordCamp and we decided to stay a couple of weeks more and visit some places to enjoy this is amazing nature and get closer to the Costa Rica people.</span></p>\n<p><img class=\"alignnone size-full wp-image-974244\" src=\"https://yithemes.com/wp-content/uploads/2018/09/04.png\" alt=\"YITH developers in Costa Rica\" width=\"1000\" height=\"500\" srcset=\"https://yithemes.com/wp-content/uploads/2018/09/04.png 1000w, https://yithemes.com/wp-content/uploads/2018/09/04-363x182.png 363w, https://yithemes.com/wp-content/uploads/2018/09/04-300x150.png 300w, https://yithemes.com/wp-content/uploads/2018/09/04-768x384.png 768w, https://yithemes.com/wp-content/uploads/2018/09/04-261x131.png 261w, https://yithemes.com/wp-content/uploads/2018/09/04-311x156.png 311w, https://yithemes.com/wp-content/uploads/2018/09/04-270x135.png 270w\" sizes=\"(max-width: 1000px) 100vw, 1000px\" /></p>\n<p>&nbsp;</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:36:\"http://wellformedweb.org/CommentAPI/\";a:1:{s:10:\"commentRss\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"https://yithemes.com/blog/events/wordcamp-san-jose-what-a-beatiful-experience/feed/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:38:\"http://purl.org/rss/1.0/modules/slash/\";a:1:{s:8:\"comments\";a:1:{i:0;a:5:{s:4:\"data\";s:1:\"0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:26:\"https://yithemes.com/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";O:42:\"Requests_Utility_CaseInsensitiveDictionary\":1:{s:7:\"\0*\0data\";a:20:{s:4:\"date\";s:29:\"Fri, 10 May 2019 10:32:59 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:10:\"set-cookie\";s:137:\"__cfduid=d8d249f78f6cae78292d42b2ad510bd5d1557484379; expires=Sat, 09-May-20 10:32:59 GMT; path=/; domain=.yithemes.com; HttpOnly; Secure\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:16:\"x-xss-protection\";s:13:\"1; mode=block\";s:13:\"last-modified\";s:29:\"Thu, 09 May 2019 17:30:43 GMT\";s:4:\"etag\";s:36:\"W/\"904c689c1c39bcd8a8eb47a0d8fa78d0\"\";s:4:\"link\";a:2:{i:0;s:247:\"</wp-content/themes/yithemes/assets/css/main.min.css?ver=3.2.8>; rel=preload; as=style,</wp-includes/js/jquery/jquery.js?ver=1.12.4>; rel=\"preload\"; as=script,</wp-content/themes/yithemes/assets/js/scripts.min.js?ver=3.2.1>; rel=preload; as=script\";i:1;s:57:\"<https://yithemes.com/wp-json/>; rel=\"https://api.w.org/\"\";}s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:12:\"x-robots-tag\";s:15:\"noindex, follow\";s:14:\"x-kinsta-cache\";s:4:\"MISS\";s:16:\"content-encoding\";s:4:\"gzip\";s:22:\"x-content-type-options\";s:7:\"nosniff\";s:15:\"cf-cache-status\";s:3:\"HIT\";s:7:\"expires\";s:29:\"Sat, 11 May 2019 10:32:59 GMT\";s:13:\"cache-control\";s:21:\"public, max-age=86400\";s:25:\"strict-transport-security\";s:44:\"max-age=15552000; includeSubDomains; preload\";s:9:\"expect-ct\";s:87:\"max-age=604800, report-uri=\"https://report-uri.cloudflare.com/cdn-cgi/beacon/expect-ct\"\";s:6:\"server\";s:10:\"cloudflare\";s:6:\"cf-