(20237, 1, '2019-03-12 17:33:59', '2019-03-12 14:33:59', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Термобельё нательное активное 726 ARMYFANS - теплое, удобное и функциональное нижнее белье, способное сохранить тепло и отвести влагу от тела. Большой популярностью такое белье пользуется у людей, которые проводят много времени  на улице в холодную погоду и избавляет их от необходимости носить несколько слоев громоздкой зимней одежды, которая ограничивает движения.<br/>\r\n<br/>\r\nОтличное активное универсальное термобелье, комплект : кофта и кальсоны. Бельё плотно облегает тело, не накапливает влагу и не вытягивается. Бесшовная конструкция белья делает его использование исключительно комфортным. Добавление волокон Spandex придаёт изделиям повышенную эластичность. Вместо формообразующих элементов (вытяжек и швов) применено плетение разной плотности, благодаря чему достигается идеальное облегание, исключающее сдавливание и натирание кожи. -бесшовная технология -плетение разной плотности обеспечивает анатомическое облегание -Область применения: мультиспорт, различные виды физической активности.<br/>\r\n</div>', 'Термобельё 726 ARMYFANS', '', 'publish', 'open', 'closed', '', 'termobelyo-726-armyfans', '', '', '2019-05-08 15:02:32', '2019-05-08 12:02:32', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-18340/', 0, 'product', '', 0),
(20786, 2, '2019-03-16 19:19:37', '2019-03-16 16:19:37', '<img class=\"aligncenter size-full wp-image-20788\" src=\"https://lucky.armopt.ru/wp-content/uploads/2019/03/bryuki.jpg\" alt=\"\" width=\"685\" height=\"433\" /><img class=\"aligncenter size-full wp-image-20789\" src=\"https://lucky.armopt.ru/wp-content/uploads/2019/03/kostyumy-gorteks.jpg\" alt=\"\" width=\"566\" height=\"193\" /><img class=\"aligncenter size-full wp-image-20790\" src=\"https://lucky.armopt.ru/wp-content/uploads/2019/03/parki-i-rubashki.jpg\" alt=\"\" width=\"594\" height=\"503\" />\r\n\r\n<img class=\"aligncenter size-full wp-image-20787\" src=\"https://lucky.armopt.ru/wp-content/uploads/2019/03/sorochki.jpg\" alt=\"\" width=\"613\" height=\"189\" />\r\n\r\n<img class=\"aligncenter size-full wp-image-20791\" src=\"https://lucky.armopt.ru/wp-content/uploads/2019/03/perchatki.jpg\" alt=\"\" width=\"315\" height=\"403\" />\r\n\r\n&nbsp;', 'Размеры одежды Бундесвера', '', 'publish', 'closed', 'closed', '', 'razmery-odezhdy-bundesvera', '', '', '2019-03-16 19:19:37', '2019-03-16 16:19:37', '', 0, 'https://lucky.armopt.ru/?page_id=20786', 0, 'page', '', 0),
