(20938, 1, '2019-03-21 14:36:36', '2019-03-21 11:36:36', '[vc_row content_placement=\"middle\"][vc_column][vc_single_image image=\"20713\" img_size=\"full\" alignment=\"center\" style=\"vc_box_outline\"][vc_column_text]ОБРАТИТЕ ВНИМАНИЕ!\r\n\r\nЗАКУПКА ТОВАРА В НАШЕМ МАГАЗИНЕ ОПТОВЫМ ПОКУПАТЕЛЯМ ПРОИЗВОДИТЬСЯ МИНИМУМ НА 15 000 РУБЛЕЙ. Окончательную оптовую цену уточняйте у наших менеджеров.\r\n\r\n&nbsp;\r\n\r\nБудьте ВНИМАТЕЛЬНЫ товар бывший в употреблении продается в связках по 5-10 шт , обмену и возврату не подлежит (см. примечание в разделе товара)[/vc_column_text][/vc_column][/vc_row]', 'Оптовикам', '', 'inherit', 'closed', 'closed', '', '20711-revision-v1', '', '', '2019-03-21 14:36:36', '2019-03-21 11:36:36', '', 20711, 'https://armopt.ru/20711-revision-v1/', 0, 'revision', '', 0),
