(20714, 2, '2019-03-16 14:32:57', '2019-03-16 11:32:57', '[vc_row content_placement=\"middle\"][vc_column][vc_single_image image=\"20713\" img_size=\"full\" alignment=\"center\" style=\"vc_box_outline\"][vc_column_text]ОБРАТИТЕ ВНИМАНИЕ! ЗАКУПКА ТОВАРА В НАШЕМ МАГАЗИНЕ ОПТОВЫМ ПОКУПАТЕЛЯМ ПРОИЗВОДИТЬСЯ МИНИМУМ НА 15 000 РУБЛЕЙ. ЧТОБЫ УВИДЕТЬ ОПТОВЫЕ ЦЕНЫ НУЖНО <b>ЗАРЕГИСТРИРОВАТЬСЯ</b><b>!</b>\r\n\r\nБудьте ВНИМАТЕЛЬНЫ товар бывший в употреблении продается в связках по 5-10 шт , обмену и возврату не подлежит (см. примечание в разделе товара)[/vc_column_text][/vc_column][/vc_row]', 'Оптовикам', '', 'inherit', 'closed', 'closed', '', '20711-autosave-v1', '', '', '2019-03-16 14:32:57', '2019-03-16 11:32:57', '', 20711, 'https://lucky.armopt.ru/20711-autosave-v1/', 0, 'revision', '', 0),
