(20156, 1, '2019-03-12 17:32:52', '2019-03-12 14:32:52', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n<span style=\"color: #ff0000;\">Перчатки Тактические армии Бундесвер.Верхний материал: 98% хлопок, 2% elasthan + кожа</span><br/>\r\n<span style=\"color: #ff0000;\">Подкладка: 97% полиэстер</span><br/>\r\n<span style=\"color: #ff0000;\">Цвет: flecktarn / черный</span><br/>\r\n<span style=\"color: #ff0000;\">Вес: прибл. 150 г<br/>\r\n</span><span style=\"color: #ff0000;\">Размеры разные в связке 10 шт. Заказывать надо 10 шт. Как получаем, так и продаем. НЕ СОРТИРУЕМ</span><span style=\"color: #ff0000;\"> </span><span style=\"color: #ff0000;\"><br/>\r\n</span> </div>', 'Перчатки Bundeswehr.Флектан кожаные б/у', '', 'trash', 'closed', 'closed', '', 'perchatki-bundeswehr-flektan-kozhanye-b-u__trashed', '', '', '2019-04-25 12:29:15', '2019-04-25 09:29:15', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-17460/', 0, 'product', '', 0),
