(20412, 1, '2019-03-12 17:36:23', '2019-03-12 14:36:23', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Индивидуальный рацион питания предназначенный для питания военнослужащих при боевых действия в горах. В герметичной водонепроницаемой упаковке. Срок годности до 08.09.2018. Энергетическая ценность 5118 ккал. Масса брутто 2,2 кг.    </div>', 'Горный сухой паек (РПГ)', '', 'trash', 'closed', 'closed', '', 'gornyj-suhoj-paek-rpg-2__trashed', '', '', '2019-04-15 19:35:55', '2019-04-15 16:35:55', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-21620/', 0, 'product', '', 0),
(20413, 1, '2019-03-12 17:36:23', '2019-03-12 14:36:23', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Флаги 900х1500мм <br/>\r\nфлаг Испания<br/>\r\nфлаг России<br/>\r\nфлаг Германии<br/>\r\nфлаг Бразилии<br/>\r\nфлаг Мексики<br/>\r\nфлаг Австралии<br/>\r\nЯпонский военный флаг<br/>\r\nфлаг Италии<br/>\r\nфлаг Уэльса<br/>\r\nфлаг Израиля<br/>\r\nфлаг России<br/>\r\nфлаг пограничников \"Граница на замке\"<br/>\r\nфлаг десантников \"За ВДВ\"<br/>\r\nКанады<br/>\r\nАвстрии<br/>\r\nЕвросоюза<br/>\r\nпиратский веселый Роджер<br/>\r\nфлаг США с индейцем<br/>\r\n</div>', 'Флаги стран мира 900х1500мм в ассортименте', '', 'trash', 'closed', 'closed', '', 'flagi-stran-mira-900h1500mm-v-assortimente-2__trashed', '', '', '2019-04-15 19:36:20', '2019-04-15 16:36:20', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-21640/', 0, 'product', '', 0),
