(19996, 1, '2019-03-12 17:30:53', '2019-03-12 14:30:53', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nВ продаже оригинальные армейские зимние шапки BW.\r\nШапка многослойная:\r\nвнешняя ткань - плотная х/б ткань\r\nвнутренняя часть шерсть (к голове)+ мех (уши затылок)\r\nмежду слоями утепляющая прослойка.\r\n\r\n</div>', 'Зимняя армейская шапка BW', '', 'publish', 'open', 'closed', '', 'zimnyaya-armejskaya-shapka-bw', '', '', '2019-05-08 14:52:17', '2019-05-08 11:52:17', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-15140/', 0, 'product', '', 0),
