(19987, 1, '2019-03-12 17:30:43', '2019-03-12 14:30:43', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        НОВАЯ балаклава, Английской армии, цвет олива FR AFV CREW BALACLAVA АРМЕЙСКИЙ ОРИГИНАЛ.<br/>\r\n балаклава изготовлена из мета-арамидных волокон Nomex, которые используются в производстве термостойкой одежды. <br/>\r\nРазмер единый.    </div>', 'Балаклава FR,AFV CREWS Британия', '', 'publish', 'open', 'closed', '', 'balaklava-fr-afv-crews-britaniya', '', '', '2019-05-08 14:52:09', '2019-05-08 11:52:09', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-15000/', 0, 'product', '', 0),
