(19920, 1, '2019-03-12 17:29:47', '2019-03-12 14:29:47', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n<div>\r\n<ul>\r\n 	<li>Материал:износоустойчивый ОКСФОРД 900 с водоотталкивающими свойствами, плотностью 900 ден</li>\r\n</ul>\r\n<ul>\r\n 	<li>Два боковых кармана из капроновой сетки</li>\r\n</ul>\r\n<ul>\r\n 	<li>Подходит для взрослых и подростков!</li>\r\n</ul>\r\n<ul>\r\n 	<li>Плечевые ремни: Эргономичные плечевые ремни анатомической формы.</li>\r\n</ul>\r\n<ul>\r\n 	<li>Вентилируемая спина</li>\r\n</ul>\r\n<ul>\r\n 	<li>Особенности строения:</li>\r\n</ul>\r\n<ul>\r\n 	<li>1 основное отделение (с отделением для ноутбука до 15.6\'),</li>\r\n</ul>\r\n<ul>\r\n 	<li>1 отделение с внутренними карманами</li>\r\n</ul>\r\n<ul>\r\n 	<li>1 наружное отделение спереди</li>\r\n 	<li>ручка для транспортировки, липучка для нашивок, стропы Молле</li>\r\n 	<li>Производитель: Mr. Martin, Гонконг</li>\r\n</ul>\r\n</div>\r\n</div>', 'Тактический рюкзак 5066 coyote 30 литров', '', 'publish', 'open', 'closed', '', 'takticheskij-ryukzak-5066-coyote-30-litrov', '', '', '2019-05-08 14:52:12', '2019-05-08 11:52:12', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-13800/', 0, 'product', '', 0),
