(19516, 1, '2019-03-12 17:24:29', '2019-03-12 14:24:29', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n<span style=\"color: #ff0000;\"><br/>\r\n<span style=\"color: #000000;\">Комбинезон защитный технической службы Royal Air Forces (военно-воздушные силы Великобритании). </span>\r\n<ul>\r\n<li style=\"color: #000000;\">Застегивается на липучку</li>\r\n<li style=\"color: #000000;\">Липучки для утяжки по низу брюк. Липучки на манжетах.</li>\r\n<li style=\"color: #000000;\">1 карман на груди слева</li>\r\n<li style=\"color: #000000;\">1 большой грузовой карман на бедре</li>\r\n<li style=\"color: #000000;\">2 фальш-кармана прорезных для доступа к внутренней одежде. Застегиваются на липучку.</li>\r\n<li style=\"color: #000000;\">Манжеты на липучках</li>\r\n<li style=\"color: #000000;\">\r\n\r\n	 </li>\r\n</ul>\r\n</span> </div>', 'Комбинезон RAF Тех.служба. Оригинал. Олива.б/у', '', 'publish', 'open', 'closed', '', 'kombinezon-raf-teh-sluzhba-original-oliva-b-u', '', '', '2019-05-08 15:18:35', '2019-05-08 12:18:35', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-10880/', 0, 'product', '', 0),
(19517, 1, '2019-03-12 17:24:29', '2019-03-12 14:24:29', '', 'Комбинезон RAF Тех.служба. Оригинал. Олива.б/у - 170/92', 'Размер: 170/92', 'publish', 'closed', 'closed', '', 'kombinezon-raf-teh-sluzhba-original-oliva-b-u-170-92', '', '', '2019-05-08 15:18:14', '2019-05-08 12:18:14', '', 19516, 'https://lucky.armopt.ru/product/import-placeholder-for-10881/', 1, 'product_variation', '', 0),
