(19641, 1, '2019-03-12 17:26:09', '2019-03-12 14:26:09', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Футболка Abercrombie Fitch с длинным рукавом<br/>\r\nМатериал: хлопок<br/>\r\nОписание: круглый воротник, длинные рукава, застежки пуговицы, одноцветное изделие, логотип    </div>', 'Лонгслив Abercrombie heather clasp', '', 'trash', 'closed', 'closed', '', 'longsliv-abercrombie-heather-clasp__trashed', '', '', '2019-04-24 11:00:04', '2019-04-24 08:00:04', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-11500/', 0, 'product', '', 0),
(19642, 1, '2019-03-12 17:26:09', '2019-03-12 14:26:09', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Футболка армии Бундесвера, короткий рукав, Coyote. Оригинал! б/у<br/>\r\n<br/>\r\nОригинальная футболка, используемая Бундесвером в миротворческих миссиях, в Афганистане. Изготовлена из материала, в составе 68% хлопок и 32% полиамид.﻿<br/>\r\nдля  охотников, рыбаков, спортсменов, для турпохода, велопрогулки, для пейнтбола, страйкбола.<br/>\r\n<br/>\r\nизображение немецкого флага на рукаве;прочная, мягкая, дышащая ткань.<br/>\r\nРазмер    Выберите размер, 48/42, 46/40, 50/44, 52/46, 44/38<br/>\r\n</div>', 'Футболка Бундесвера тропическая Б/У', '', 'trash', 'closed', 'closed', '', 'futbolka-bundesvera-tropicheskaya-b-u__trashed', '', '', '2019-04-24 11:00:17', '2019-04-24 08:00:17', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-11520/', 0, 'product', '', 0),
