(19660, 1, '2019-03-12 17:26:22', '2019-03-12 14:26:22', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nТермо сапоги для экстремальных погодных условий, на резиновой нескользящей подошве, голенище из нейлона, съемная войлочная вставка на фольге, с воротником • Материал верха: нейлон, подошва: резина, подкладка: войлок\r\n\r\n</div>', 'ТЕРМО САПОГИ  \"FoX Outdoor XTREME\"', '', 'publish', 'open', 'closed', '', 'termo-sapogi-fox-outdoor-xtreme', '', '', '2019-05-08 15:18:34', '2019-05-08 12:18:34', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-11600/', 0, 'product', '', 0),
