(19730, 1, '2019-03-12 17:27:28', '2019-03-12 14:27:28', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nОригинальный полевой костюм M-92 BDU итальянских вооруженных сил.\r\n\r\nРасцветка Woodland.\r\n\r\nКостюм состоит из полевой рубашки , брюк и кепки\r\n\r\nПлотная но мягкая ткань (100% хлопок!).\r\n\r\nБрюки:\r\n\r\nШиринка на молнии.\r\n\r\n2 боковых прорезных кармана.\r\n\r\n2 грузовых кармана на бедрах.\r\n\r\n2 кармана сзади.\r\n\r\nНиз брючин имеет встроенные эластичные резинки.\r\n\r\nРубашка:\r\n\r\nЗастегивается на пуговицы.\r\n\r\nМанжеты на пуговицах.\r\n\r\nНа воротнике нашивки со звездами.\r\n\r\nКарманы на рукавах.\r\n\r\n</div>', 'Костюм Италия woodland', '', 'publish', 'open', 'closed', '', 'kostyum-italiya-woodland', '', '', '2019-05-08 15:18:34', '2019-05-08 12:18:34', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-12040/', 0, 'product', '', 0),
