(20330, 1, '2019-03-12 17:35:16', '2019-03-12 14:35:16', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n<span style=\"color: #ff0000;\">связка 5 шт. Надо ложить в корзину соответственное количество 5  Будьте ВНИМАТЕЛЬНЫ. Размеры в связке разные</span>\r\n\r\nСтильный, добротный, отменный кожаный ремень высокого качества с пряжкой из высококачественного металла. На бляхе выгравировано изображение раскинувшего крылья орла с надписью Einigkeit, Recht, Freiheit (нем. Единство, Право, Свобода). С 1962 г. это девиз армии Бундесвера.<br/>\r\n\r\n Материал: кожа;<br/>\r\n\r\nШирина: 5 см    </div>', 'Ремень парадный Bundeswehr. Кожаный Б/У (продаётся оптом)', '', 'publish', 'open', 'closed', '', 'remen-paradnyj-bundeswehr-kozhanyj-b-u-prodayotsya-optom', '', '', '2019-05-08 15:02:23', '2019-05-08 12:02:23', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-20000/', 0, 'product', '', 0),
