(20193, 1, '2019-03-12 17:33:24', '2019-03-12 14:33:24', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Оригинальные гамаши Британской армии, камуфляжной расцветки DPM .  Препятствуют попаданию снега и грязи в обувь, а также являются дополнительной (но не основной) защитой от холода. Используются и зимой, и летом без ограничений по температурам.  Имеются специальные крючки (зацепы) для фиксации гамаши на ноге за шнуровку ботинка или берца    </div>', 'Гетры (бахилы) гортекс ДПМ б/у', '', 'publish', 'open', 'closed', '', 'getry-bahily-gorteks-dpm-b-u', '', '', '2019-05-08 15:02:30', '2019-05-08 12:02:30', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-18140/', 0, 'product', '', 0),
(20194, 1, '2019-03-12 17:33:24', '2019-03-12 14:33:24', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Производитель: Армейские склады (Великобритания)<br/>\r\nСостояние: Новые<br/>\r\nСостав: Мембрана.<br/>\r\nНепромокаемые (мембрана) гетры ВС Великобритании в расцветке Олива.<br/>\r\nМаркировка Gaters SNOW MK11.<br/>\r\nВысота: 44 см.<br/>\r\nГетры из мембраны (Gore-Tex) это хорошее решение для защиты ног от воды и снега. Одеваются поверх брюк, сверху затягиваются резинкой с фиксатором, снизу пристегиваются ремешком через подошву. Размера не имеют - универсальны для любого размера. Гетры легко снять и одеть - они полностью расстегиваются с помощью крупной молнии и липучки по всей длине клапана молнии. <br/>\r\nПользуются большой популярностью у тех кто не хочет одевать непромокаемые брюки при передвижении по мокрой траве, для \"покатушек\" на квадроциклах.    </div>', 'Гетры (гамаши) непромокаемые MK11 (мембрана)', '', 'publish', 'open', 'closed', '', 'getry-gamashi-nepromokaemye-mk11-membrana', '', '', '2019-05-08 15:02:30', '2019-05-08 12:02:30', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-18160/', 0, 'product', '', 0),
