(20099, 1, '2019-03-12 17:32:09', '2019-03-12 14:32:09', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nGB Подсумок, COMMANDERS, Osprey MK IV, MTP camo, б/у\r\n\r\n</div>', 'Подсумок Osprey MTP Admin Pouch', '', 'publish', 'open', 'closed', '', 'podsumok-osprey-mtp-admin-pouch', '', '', '2019-05-08 14:52:03', '2019-05-08 11:52:03', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-16540/', 0, 'product', '', 0),
