(20043, 1, '2019-03-12 17:31:34', '2019-03-12 14:31:34', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        новая шапка GB Cold Weather Gore-tex (теплая мембранная шапка - мембрана GT + флис ), уши заворачиваются, резинка под подбородком, размер \' M \' ( 56-58 ), цвет - камуфляж DPM <br/>\r\nТеплая мембранная шапка с флисовой подкладкой и жесткой проволочной  вставкой в козырьке. Имеется регулировка размера \"в минус\" от номинального. \"Уши\" могут быть застегнуты над головой либо под подбородком. <br/>\r\n</div>', 'Шапка Англия DPM мембрана флис', '', 'publish', 'open', 'closed', '', 'shapka-angliya-dpm-membrana-flis', '', '', '2019-05-08 14:52:06', '2019-05-08 11:52:06', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-15900/', 0, 'product', '', 0),
(20044, 1, '2019-03-12 17:31:34', '2019-03-12 14:31:34', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Оригинальная армейская зимняя шапка BW.<br/>\r\nШапка многослойная:<br/>\r\nвнешняя ткань - плотная х/б ткань<br/>\r\nвнутренняя часть шерсть (к голове)+ мех (уши затылок)<br/>\r\nмежду слоями утепляющая прослойка.    </div>', 'Зимняя армейская шапка BW олива', '', 'publish', 'open', 'closed', '', 'zimnyaya-armejskaya-shapka-bw-oliva', '', '', '2019-05-08 14:52:17', '2019-05-08 11:52:17', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-15920/', 0, 'product', '', 0),
