(19077, 1, '2019-03-12 17:18:18', '2019-03-12 14:18:18', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nХарактеристики: Куртка зимняя Аляска N-3B Olive\r\nСезон: Зимний\r\nТемпературный режим: до -35С\r\nСтиль: Повседневный (casual)\r\nМатериал наполнителя: холлофайбер\r\nОсобенности модели: Металлическая молния\r\nЦвет: Оливковый\r\n\r\n</div>', 'Куртка аляска Alpha Industries slim Fit N-3B', '', 'publish', 'open', 'closed', '', 'kurtka-alyaska-alpha-industries-slim-fit-n-3b', '', '', '2019-05-08 15:18:36', '2019-05-08 12:18:36', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-8620/', 0, 'product', '', 0),
