(21280, 1, '2019-04-04 14:13:50', '2019-04-04 11:13:50', '<div class=\"description_detail\">\n<div class=\"title\">Описание</div>\nПредставляем вашему вниманию костюм военных сил Британии.\nБританские MTP костюм куртка, штаны изготовлены из Goretex трёхслойного ламинированного материала, состоящего из водоотталкивающего слоя, барьерного и внутренний дышащий слой. Благодаря этому материалу вы будите защищены от средних и тяжелых ливней.\nОсновные свойства материала Goretex:\n•    Активный дышащий слой позволит не упреть.\n•    Долго сохранять водонепроницаемость.\n•    Морозостойкость.\n•    Устойчив к изгибам, стиркам.\n•    Долговечен в использовании.\n\n</div>', 'Комплект  Lightweight Waterproof Trousers,MTP б.у.', '', 'inherit', 'closed', 'closed', '', '19739-autosave-v1', '', '', '2019-04-04 14:13:50', '2019-04-04 11:13:50', '', 19739, 'https://armopt.ru/19739-autosave-v1/', 0, 'revision', '', 0),
(19146, 1, '2019-03-12 17:19:14', '2019-03-12 14:19:14', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nАнглийские боевые брюки Temporate MTP Camo - оригинальные британские армейские камуфляжные брюки. Ширинка на молнии. Имеют четыре передних кармана (два боковых прорезных, два набедренных на пуговицах с клапанами) и один задний карман с клапаном. В нижней части штанин утяжки. На поясе петли под широкий пистолетный ремень. Материал: 67% полиэстер, 33% хлопок.\r\nСостояние: новые\r\n\r\n</div>', 'БРЮКИ GB TEMPORATE, MTP', '', 'publish', 'open', 'closed', '', 'bryuki-gb-temporate-mtp-b-u', '', '', '2019-05-08 15:18:36', '2019-05-08 12:18:36', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-9360/', 0, 'product', '', 0),
(19147, 1, '2019-03-12 17:19:15', '2019-03-12 14:19:15', '', 'БРЮКИ GB TEMPORATE, MTP', '', 'publish', 'closed', 'closed', '', 'bryuki-gb-temporate-mtp-b-u-80-80-96', '', '', '2019-05-08 15:18:22', '2019-05-08 12:18:22', '', 19146, 'https://lucky.armopt.ru/product/import-placeholder-for-9361/', 1, 'product_variation', '', 0),
(19148, 1, '2019-03-12 17:19:15', '2019-03-12 14:19:15', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Оригинальные полевые брюки британской армии <span><br/>\r\n<br/>\r\n\r\n Характеристики:<br/>\r\n\r\n - регулируемый с помощью пуговиц пояс (возможность уменьшить объем на 2-4 см.);<br/>\r\n\r\n - 2 прорезных кармана с клапаном на липучках;<br/>\r\n\r\n - 1 задний карман на пуговице;<br/>\r\n\r\n - 2 кармана карго на штанинах;<br/>\r\n\r\n - застежка на липучке снизу штанин для удобства при надевании/снятии, либо при необходимости расклешить на широкую обувь;<br/>\r\n\r\n - утяжка снизу штанин;<br/>\r\n\r\n - ширинка на молнии;<br/>\r\n\r\n - широкие шлевки;<br/>\r\n\r\n СОСТОЯНИЕ - НОВЫЕ.<br/>\r\n</span>Ткань: <span>50% хлопка и 50% полиэстера.<br/>\r\n<br/>\r\n</span> </div>', 'Брюки DDPM , новые', '', 'publish', 'open', 'closed', '', 'bryuki-ddpm-novye', '', '', '2019-05-08 15:18:22', '2019-05-08 12:18:22', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-9380/', 0, 'product', '', 0),
