(19809, 1, '2019-03-12 17:28:25', '2019-03-12 14:28:25', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Брюки +китель Германия Тропентарн оригинал Материал 65%полиэстр 35%хлопок. <br/>\r\n<br/>\r\nБрюки имеют два кармана сзади, два кармана боковых, и два кармана накладных с лентами для утяжки. Низ брюк утягивается лентой.<br/>\r\n<br/>\r\nПолевая рубашка Бундесвера, с двумя нагрудными карманами и одним накладным карманом на рукаве слева    </div>', 'Костюм летний BW tropentarn б/у', '', 'publish', 'open', 'closed', '', 'kostyum-letnij-bw-tropentarn-b-u', '', '', '2019-05-08 14:52:18', '2019-05-08 11:52:18', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-12440/', 0, 'product', '', 0),
