(19811, 1, '2019-03-12 17:28:26', '2019-03-12 14:28:26', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n<b>Новые, продаются только в связке по 3 шт (1шт-50 и 2шт-48 размера)</b> </div>', 'Свитер верблюжий горный Австрия', '', 'publish', 'open', 'closed', '', 'sviter-verblyuzhij-gornyj-avstriya', '', '', '2019-05-08 14:52:15', '2019-05-08 11:52:15', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-12460/', 0, 'product', '', 0),
(19812, 1, '2019-03-12 17:28:26', '2019-03-12 14:28:26', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n<span style=\"color: #ff0000;\">Внимание продаются по 10 штук!<br/>\r\n<span style=\"color: #000000;\"><br/>\r\n</span><span style=\"color: #000000;\">Производитель: армейский оригинал</span><br/>\r\n<span style=\"color: #000000;\">\r\n\r\nМатериал: 100% полиестер </span><br/>\r\n<span style=\"color: #000000;\">\r\n\r\nОсобенности: Удлиненная задняя часть . В манжетах рукавов есть прорезь под большой палец </span><br/>\r\n<span style=\"color: #000000;\">\r\n\r\nПримечания: Снаружи мягкий и приятный на ощупь флис с внутренней стороны влагоотводящий слой как у футболок coolmax</span><br/>\r\n</span> </div>', 'Термо-Флис Combat undershirt thermal PCS Light Olive (2-й слой)', '', 'trash', 'closed', 'closed', '', 'termo-flis-combat-undershirt-thermal-pcs-light-olive-2-j-sloj__trashed', '', '', '2019-05-02 11:48:22', '2019-05-02 08:48:22', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-12480/', 0, 'product', '', 0),
