(18742, 1, '2019-03-12 17:14:21', '2019-03-12 14:14:21', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n<span style=\"color: #ff0000;\">Еще одна великолепная демисезонная ветровка британских военных - куртка-парка DPM («лесной камуфляж»). Удобная, легкая и практичная армейская куртка, которая идеально подходит для активного отдыха: рыбалки, охоты, турпоходов и так далее. Кстати, данный вид камуфляжной расцветки очень эффективен при использовании в средней лесной полосе, что может стать настоящей находкой для егерей, охотников и страйкболистов.</span>\r\n\r\nКуртка-парка отлично защищает от холода и сырости, а благодаря проволочному канту даже очень сильный ветер не сумеет сорвать с вас ее капюшон.\r\n\r\nДанная модель имеет двойную застежку - и пуговицы, и молнию, а также снабжена вместительными накладными карманами и шнурами-утяжками (на талии и в нижней части).\r\n\r\nСостояние: б.у.\r\n\r\n</div>', 'Куртка SAS DPM Британия. Оригинал', '', 'publish', 'open', 'closed', '', 'kurtka-sas-dpm-britaniya-original', '', '', '2019-05-08 15:18:37', '2019-05-08 12:18:37', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-7400/', 0, 'product', '', 0),
(18743, 1, '2019-03-12 17:14:21', '2019-03-12 14:14:21', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nКопия куртки М65 в расцветке флектарн , с подстежкой\r\n\r\n</div>', 'Куртка М-65  (реплика) flecktarn', '', 'publish', 'open', 'closed', '', 'kurtka-m-65-replika-flecktarn', '', '', '2019-05-08 15:18:37', '2019-05-08 12:18:37', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-7420/', 0, 'product', '', 0),
