(18749, 1, '2019-03-12 17:14:23', '2019-03-12 14:14:23', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\nПарка Security Комфорт\r\nПарка Security с вынимаемой внутренней курткой из флиса - идеальный вариант для служб безопасности, охранников и т.д.\r\n\r\nХарактеристики:\r\n- отстегиваемые с помощью молнии рукава на внутренней и наружной куртках,\r\n- сетчатая вставка на спинке,\r\n- утяжка по линии талии,\r\n- сворачиваемый в воротник капюшон,\r\n- 2 нагрудных прорезных кармана на молниях с клапанами,\r\n- 6 накладных передних кармана на кнопках или липучках,\r\n- 2 боковых кармана на молниях,\r\n- 1 нагрудный прорезной карман на молнии слева,\r\n- пристегиваемые с помощью молнии нашивки Security спереди и сзади (сзади возможно крепление также с помощью липучки).\r\n\r\n</div>', 'Куртка Security MFH (2 в1)', '', 'publish', 'open', 'closed', '', 'kurtka-security-mfh-2-v1', '', '', '2019-05-08 15:18:37', '2019-05-08 12:18:37', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-7440/', 0, 'product', '', 0),
