(18699, 1, '2019-03-12 17:13:55', '2019-03-12 14:13:55', '<div class=\"description_detail\">\r\n<div class=\"title\">Описание</div>\r\n        Оригинальная униформа немецких матросов-подводников. <br/>\r\n<br/>\r\nИдеальный вариант для мотоциклистов:<br/>\r\n- рукава сшиты для согнутых рук;<br/>\r\n- система вентиляции под мышками.<br/>\r\n2 внутренних кармана, на воротнике имеется застёжка-петля,<br/>\r\nзастёжка-молния, молнии на рукавах.<br/>\r\nматериал – 100% кожа, <br/>\r\nСостояние б.у.    </div>', 'Куртка подводника BW б/у', '', 'publish', 'open', 'closed', '', 'kurtka-podvodnika-bw-b-u', '', '', '2019-05-08 15:18:37', '2019-05-08 12:18:37', '', 0, 'https://lucky.armopt.ru/product/import-placeholder-for-7240/', 0, 'product', '', 0),
